// Normaliza un texto a slug ASCII en minúsculas, sin espacios ni signos.
function _slug(s) {
  return (s||'').toString().toLowerCase()
    .replace(/[áàä]/g,'a').replace(/[éèë]/g,'e').replace(/[íìï]/g,'i')
    .replace(/[óòö]/g,'o').replace(/[úùü]/g,'u').replace(/ñ/g,'n')
    .replace(/[^a-z0-9]/g,'');
}

// Slug del último GP disputado: primera palabra del nombre del último race.
// Usado para resolver assets/head/<gp>N_head.webp dinámicamente.
function _lastGpSlug() {
  if (!S.races || !S.races.length) return null;
  const last = S.races[S.races.length-1];
  const cleanName = (last.name||'').replace(/^gp\s+/i,'')
    .replace(/^gran\s+premio\s+(de\s+)?/i,'').trim();
  const first = cleanName.split(/[\s,]+/)[0];
  return _slug(first) || null;
}

// Lee la imagen como base64 desde el sitio que le toca en S (compat JSONs viejos).
function _imgFromS(key) {
  if (!key || !S) return null;
  if (key.startsWith('dp_')) return S.driverProfiles && S.driverProfiles[key.slice(3)] && S.driverProfiles[key.slice(3)].photoDataUrl;
  if (key.startsWith('pb_')) return S.driverProfiles && S.driverProfiles[key.slice(3)] && S.driverProfiles[key.slice(3)].photoB;
  if (key.startsWith('ti_')) return S.driverProfiles && S.driverProfiles[key.slice(3)] && S.driverProfiles[key.slice(3)].teamImgUrl;
  if (key.startsWith('layout_')) {
    const id = key.slice(7);
    const r = (S.races||[]).find(r => String(r.id) === id);
    return r && r.layoutDataUrl;
  }
  if (key.startsWith('hem_')) {
    const e = (S.hemeroteca||[]).find(e => String(e.id) === key.slice(4));
    return e && e.img;
  }
  if (key.startsWith('flogo_')) return (S.footerLogos||[])[parseInt(key.slice(6),10)];
  if (key.startsWith('coverImg_')) return S.coverImages && S.coverImages[key.slice(9)];
  if (key.startsWith('cover_')) {
    const slot = key.slice(6);
    return (S.coverBgs && S.coverBgs[slot]) || (S.coverImages && S.coverImages[slot]);
  }
  if (key.startsWith('logo_')) return S.logos && S.logos[key.slice(5)];
  if (key.startsWith('noticia_')) {
    const i = parseInt(key.slice(8),10);
    return (S.noticias||[])[i] && (S.noticias||[])[i].photo;
  }
  return null;
}

// Resuelve a una ruta de fichero (assets/...) para las entradas dinámicas
// (las que dependen del piloto, del GP, etc.).
function _imgResolveDynamic(key) {
  if (key.startsWith('dp_') || key.startsWith('pb_')) {
    const id = key.slice(3);
    const drv = (S.drivers||[]).find(d => String(d.id) === id);
    if (!drv) return null;
    const slug = _slug(drv.name);
    if (!slug) return null;
    return key[0] === 'd'
      ? `assets/drivers/driver_${slug}.webp`
      : `assets/cards/card_${slug}.webp`;
  }
  if (key.startsWith('ti_')) {
    const id = key.slice(3);
    const drv = (S.drivers||[]).find(d => String(d.id) === id);
    if (!drv) return null;
    const abbr = TEAM_FILE_ABBR[drv.team] || (drv.team||'').replace('team-','');
    if (!abbr) return null;
    return `assets/teams/esc_${abbr}_small.webp`;
  }
  if (key.startsWith('layout_')) {
    const id = key.slice(7);
    const race = (S.races||[]).find(r => String(r.id) === id);
    if (!race) return null;
    const cleanName = (race.name||'').replace(/^gp\s+/i,'')
      .replace(/^gran\s+premio\s+(de\s+)?/i,'').trim();
    const first = cleanName.split(/[\s,]+/)[0];
    const slug = _slug(first);
    if (!slug) return null;
    return `assets/layouts/${slug}_layout.webp`;
  }
  // coverImg_hero, coverImg_hero2, coverImg_hero3 -> assets/head/<lastgp>N_head.webp
  const heroMatch = key.match(/^coverImg_hero(\d*)$/);
  if (heroMatch) {
    const n = heroMatch[1] || '1';
    const slug = _lastGpSlug();
    if (!slug) return null;
    return `assets/head/${slug}${n}_head.webp`;
  }
  // noticia_<i> -> assets/news/<idxCron>_news.webp (orden cronologico
  // inverso: la noticia mas antigua del array es 0_news, la mas
  // reciente es (N-1)_news). Si la noticia tiene n.imgName lo respeta.
  if (key.startsWith('noticia_')) {
    const i = parseInt(key.slice(8),10);
    const arr = S.noticias || [];
    if (i < 0 || i >= arr.length) return null;
    const n = arr[i];
    if (n && n.imgName) return `assets/news/${n.imgName}.webp`;
    const idxCron = (arr.length - 1) - i;
    return `assets/news/${idxCron}_news.webp`;
  }
  // circuitPhoto_<raceId> -> assets/photos/r<round>_photo.webp
  if (key.startsWith('circuitPhoto_')) {
    const id = key.slice(13);
    const race = (S.races||[]).find(r => String(r.id) === id);
    if (!race) return null;
    return `assets/photos/r${race.round}_photo.webp`;
  }
  // trophy_<round> -> assets/trophies/r<round>_trophy.webp
  if (key.startsWith('trophy_')) {
    const round = key.slice(7);
    return `assets/trophies/r${round}_trophy.webp`;
  }
  return null;
}

// Punto único de uso desde renders. Devuelve URL para <img src="..."> o null.
function imgSrc(key) {
  const raw = _imgFromS(key);
  if (raw && typeof raw === 'string' && raw.indexOf('data:') === 0) return raw;
  if (IMG_STATIC[key]) return IMG_STATIC[key];
  return _imgResolveDynamic(key);
}

