let S = {
  championshipTitle: 'LEALA F1 WORLD CHAMPIONSHIP 2026',
  drivers: [],
  races: [],
  pointsSystem: {},
  driverProfiles: {}
};

function saveState(immediate) {
  _dataVersion++;
  if (_saveTimer) clearTimeout(_saveTimer);
  const delay = immediate ? 0 : 300;
  _saveTimer = setTimeout(() => {
  try {
    const images = {};
    const profilesClean = {};
    Object.entries(S.driverProfiles||{}).forEach(([id, p]) => {
   profilesClean[id] = { bio: p.bio||'' };
   if (p.photoDataUrl)  images[`dp_${id}`]  = p.photoDataUrl;
   if (p.teamImgUrl)    images[`ti_${id}`]  = p.teamImgUrl;
    });
    // Save cover backgrounds as images
    if(S.coverBgs) { Object.entries(S.coverBgs).forEach(([k,v]) => { if(v) images[`cover_${k}`]=v; }); }
    const logosClean = {};
    Object.entries(S.logos||{}).forEach(([k, v]) => { images[`logo_${k}`] = v; });
    const racesClean = (S.races||[]).map(r => {
   const { layoutDataUrl, ...rest } = r;
   if (layoutDataUrl) images[`layout_${r.id}`] = layoutDataUrl;
   return rest;
    });
    const hemClean=(S.hemeroteca||[]).map(({img,...rest})=>rest);
    const {coverImages: _ci, hemeroteca: _hem, footerLogos: _fl, ...sRest} = S;
    const slim = { ...sRest, hemeroteca: hemClean, driverProfiles: profilesClean, logos: logosClean, races: racesClean };
    localStorage.setItem('leala_v2', JSON.stringify(slim));
    // Save cover images
    Object.entries(S.coverImages||{}).forEach(([k,v])=>{ images['cover_'+k]=v; });
    (S.footerLogos||[]).forEach((v,i)=>{ if(v) images['flogo_'+i]=v; });
    (S.hemeroteca||[]).forEach(e=>{ if(e.img){ images['hem_'+e.id]=e.img; } });
    localStorage.setItem('leala_v2_img', JSON.stringify(images));
    updateLastSaved();
  } catch(e) { console.error('saveState error:', e); }
  }, delay);
}

function loadState() {
  _dataVersion++;
  try {
  const s = localStorage.getItem('leala_v2');
  if (!s) return;
  S = JSON.parse(s);
  if (!S.driverProfiles) S.driverProfiles = {};
  if (!S.calendario) S.calendario = [];
  if (!S.noticias) S.noticias = [];
  if (!S.logos) S.logos = {};
  const imgRaw = localStorage.getItem('leala_v2_img');
  if (imgRaw) {
    const images = JSON.parse(imgRaw);
    Object.entries(images).forEach(([k, v]) => {
   if (k.startsWith('dp_')) {
     const id = parseInt(k.slice(3));
     if (!S.driverProfiles[id]) S.driverProfiles[id] = {};
     S.driverProfiles[id].photoDataUrl = v;
   } else if (k.startsWith('ti_')) {
     const id = parseInt(k.slice(3));
     if (!S.driverProfiles[id]) S.driverProfiles[id] = {};
     S.driverProfiles[id].teamImgUrl = v;
   } else if (k.startsWith('pb_')) {
     const id = parseInt(k.slice(3));
     if (!S.driverProfiles[id]) S.driverProfiles[id] = {};
     S.driverProfiles[id].photoB = v;
   } else if (k.startsWith('logo_')) {
     S.logos[k.slice(5)] = v;
   } else if (k.startsWith('flogo_')) {
          const fi = parseInt(k.slice(6));
          if(!S.footerLogos) S.footerLogos=[];
          S.footerLogos[fi] = v;
      } else if (k.startsWith('hem_')) {
          const eid = k.slice(4);
          const entry = (S.hemeroteca||[]).find(e=>e.id===eid);
          if(entry) entry.img = v;
      } else if (k.startsWith('cover_')) {
          const slot = k.slice(6);
          if(!S.coverBgs) S.coverBgs={};
          S.coverBgs[slot] = v;
        } else if (k.startsWith('layout_')) {
     const id = parseInt(k.slice(7));
     const race = (S.races||[]).find(r => r.id === id);
     if (race) race.layoutDataUrl = v;
   }
    });
  }
  } catch(e) { console.error('loadState error:', e); }
}

