// Exporta SOLO datos del Mundial — sin imágenes base64. Para data/data.json.
function exportDataClean() {
  const PURE_KEYS = ['championshipTitle','drivers','pointsSystem','circuitPress',
    'penalties','pinEnabled','adminPin','coverTitle','selectedFont','lightMode',
    'coverSubtitle','fontGroups','calendario','videos','hemeroteca','deletedRaces',
    'coverBgs','timeTrials','circuitHistory'];
  const out = {};
  PURE_KEYS.forEach(k => { if (S[k] !== undefined) out[k] = S[k]; });
  // races sin layoutDataUrl
  out.races = (S.races||[]).map(r => {
    const {layoutDataUrl, ...rest} = r;
    return rest;
  });
  // driverProfiles solo bio
  out.driverProfiles = {};
  Object.entries(S.driverProfiles||{}).forEach(([id,p]) => {
    if (p && p.bio) out.driverProfiles[id] = {bio: p.bio};
  });
  // noticias sin photo
  out.noticias = (S.noticias||[]).map(n => {
    const {photo, ...rest} = n;
    return rest;
  });
  const json = JSON.stringify(out);
  const sizeKB = (json.length/1024).toFixed(1);
  const b = new Blob([json], {type:'application/json'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(b);
  a.download = 'data.json';
  a.click();
  if (typeof showNotif==='function') showNotif(`✓ data.json descargado (${sizeKB} KB)`);
}

function importData(evt) {
  const f = evt ? evt.target.files[0] : null;
  if(!f) return;
  const r = new FileReader();
  r.onload = ev => {
    try {
      const imported = JSON.parse(ev.target.result);
      // Merge: keep existing images, override data fields
      const preserve = {
        driverProfiles: S.driverProfiles,
        logos: S.logos,
        coverImages: S.coverImages,
        hemeroteca: S.hemeroteca,
        footerLogos: S.footerLogos,
        customFonts: S.customFonts,
      };
      S = Object.assign({}, imported);
      // Restore images if not in import
      if(!S.driverProfiles) S.driverProfiles = preserve.driverProfiles||{};
      if(!S.logos) S.logos = preserve.logos||{};
      if(!S.coverImages) S.coverImages = preserve.coverImages||{};
      if(!S.hemeroteca) S.hemeroteca = preserve.hemeroteca||[];
      if(!S.footerLogos) S.footerLogos = preserve.footerLogos||[];
      if(!S.customFonts) S.customFonts = preserve.customFonts||{};
      // Ensure required arrays exist
      if(!S.penalties) S.penalties = [];
      if(!S.races) S.races = [];
      if(!S.drivers) S.drivers = [];
      saveState();
      render();
      initCover();
      renderFooterLogos();
      updateNavAccent();
      showNotif('✅ Datos importados: ' + (S.races?.length||0) + ' carreras, ' + (S.penalties?.length||0) + ' sanciones');
    } catch(e) {
      showNotif('⚠ Error al importar: ' + e.message);
    }
  };
  r.readAsText(f);
}

// ─────────────────────────────────────────────────────────────────────
// EXPORTAR IMÁGENES — descarga las imágenes base64 que están en S
// como ficheros .webp sueltos, con el nombre que les toca según el
// naming map. Se descargan una a una (sin librerías externas).
// Para las noticias, se nombran por orden cronológico inverso:
// la más antigua => 0_news, la más reciente => (N-1)_news.
// ─────────────────────────────────────────────────────────────────────
function exportImagesAll() {
  const items = [];   // {name, dataUrl}

  // Logos generales
  Object.entries(S.logos||{}).forEach(([k,v]) => {
    if (!v || typeof v !== 'string' || !v.startsWith('data:')) return;
    const key = 'logo_'+k;
    const path = IMG_STATIC[key];
    if (path) items.push({name: path.split('/').pop(), dataUrl: v});
  });
  // Sponsors
  (S.footerLogos||[]).forEach((v,i) => {
    if (!v || typeof v !== 'string' || !v.startsWith('data:')) return;
    const path = IMG_STATIC['flogo_'+i];
    if (path) items.push({name: path.split('/').pop(), dataUrl: v});
  });
  // Fondos de portada — los 3 fijos y los 3 rotativos (hero)
  Object.entries(S.coverImages||{}).forEach(([k,v]) => {
    if (!v || typeof v !== 'string' || !v.startsWith('data:')) return;
    const key = 'coverImg_'+k;
    const path = IMG_STATIC[key] || _imgResolveDynamic(key);
    if (path) items.push({name: path.split('/').pop(), dataUrl: v});
  });
  Object.entries(S.coverBgs||{}).forEach(([k,v]) => {
    if (!v || typeof v !== 'string' || !v.startsWith('data:')) return;
    const key = 'cover_'+k;
    const path = IMG_STATIC[key];
    if (path) items.push({name: path.split('/').pop(), dataUrl: v});
  });
  // Pilotos: foto A, foto B, escudo del equipo (este último de-duplicado)
  const seenTeam = new Set();
  Object.entries(S.driverProfiles||{}).forEach(([id, prof]) => {
    if (!prof) return;
    [['dp_','photoDataUrl'],['pb_','photoB']].forEach(([prefix,field]) => {
      const v = prof[field];
      if (v && typeof v==='string' && v.startsWith('data:')) {
        const path = _imgResolveDynamic(prefix+id);
        if (path) items.push({name: path.split('/').pop(), dataUrl: v});
      }
    });
    if (prof.teamImgUrl && typeof prof.teamImgUrl==='string' && prof.teamImgUrl.startsWith('data:')) {
      const path = _imgResolveDynamic('ti_'+id);
      if (path && !seenTeam.has(path)) {
        seenTeam.add(path);
        items.push({name: path.split('/').pop(), dataUrl: prof.teamImgUrl});
      }
    }
  });
  // Layouts de circuitos
  (S.races||[]).forEach(r => {
    if (r.layoutDataUrl && r.layoutDataUrl.startsWith('data:')) {
      const path = _imgResolveDynamic('layout_'+r.id);
      if (path) items.push({name: path.split('/').pop(), dataUrl: r.layoutDataUrl});
    }
  });
  // Noticias — orden cronológico inverso: la última del array => 0_news
  const noticias = (S.noticias||[]).slice();
  noticias.forEach((n,i) => {
    if (n && n.photo && n.photo.startsWith('data:')) {
      const idxCron = (noticias.length-1) - i;
      items.push({name: idxCron+'_news.webp', dataUrl: n.photo});
    }
  });

  if (!items.length) { showNotif('No hay imágenes base64 que exportar'); return; }

  showNotif('Descargando '+items.length+' imágenes...');
  // Descargas escalonadas: el navegador no admite muchas simultáneas.
  let i = 0;
  function next() {
    if (i >= items.length) { showNotif('✅ Imágenes exportadas: '+items.length); return; }
    const it = items[i++];
    const a = document.createElement('a');
    a.href = it.dataUrl;
    a.download = it.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(next, 250);
  }
  next();
}

// ─────────────────────────────────────────────────────────────────────
// IMPORTAR IMÁGENES — lee N ficheros .webp/.png/.jpg sueltos, los mete
// en S como base64 con la clave que corresponde según su nombre. Hace
// el match inverso del naming map.
// ─────────────────────────────────────────────────────────────────────
function importImagesMulti(evt) {
  const files = Array.from(evt.target.files || []);
  if (!files.length) return;

  // Construir mapa inverso: nombre_fichero -> clave interna en S
  const reverse = new Map();
  // 1) entradas estáticas
  for (const [key, path] of Object.entries(IMG_STATIC)) {
    const fname = path.split('/').pop();
    if (!reverse.has(fname)) reverse.set(fname, []);
    reverse.get(fname).push(key);
  }
  // 2) entradas dinámicas que conocemos AHORA (pueden cambiar; al usar
  //    el importador, miramos S vigente)
  (S.drivers||[]).forEach(d => {
    const slug = _slug(d.name);
    if (slug) {
      reverse.set('driver_'+slug+'.webp', ['dp_'+d.id]);
      reverse.set('card_'+slug+'.webp',   ['pb_'+d.id]);
    }
    const abbr = TEAM_FILE_ABBR[d.team] || (d.team||'').replace('team-','');
    if (abbr) {
      const fname = 'esc_'+abbr+'_small.webp';
      if (!reverse.has(fname)) reverse.set(fname, []);
      reverse.get(fname).push('ti_'+d.id);
    }
  });
  (S.races||[]).forEach(r => {
    const cleanName = (r.name||'').replace(/^gp\s+/i,'')
      .replace(/^gran\s+premio\s+(de\s+)?/i,'').trim();
    const first = cleanName.split(/[\s,]+/)[0];
    const slug = _slug(first);
    if (slug) reverse.set(slug+'_layout.webp', ['layout_'+r.id]);
  });
  // 3) hero rotativos del último GP
  const lastSlug = _lastGpSlug();
  if (lastSlug) {
    ['','2','3'].forEach((n,i) => {
      const idx = String(i+1).replace('1','');
      reverse.set(lastSlug+(i+1)+'_head.webp', ['coverImg_hero'+(i===0?'':String(i+1))]);
    });
  }
  // 4) noticias: <N>_news.webp donde N es índice cronológico inverso
  (S.noticias||[]).forEach((n,i) => {
    const idxCron = ((S.noticias||[]).length-1) - i;
    reverse.set(idxCron+'_news.webp', ['__noticia__'+i]);
  });

  let done = 0, ignored = [];
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = ev => {
      const dataUrl = ev.target.result;
      const fname = file.name;
      const keys = reverse.get(fname);
      if (!keys || !keys.length) {
        ignored.push(fname);
      } else {
        keys.forEach(key => _writeImgToS(key, dataUrl));
      }
      done++;
      if (done === files.length) {
        saveState(true);
        render();
        initCover();
        renderFooterLogos();
        if (ignored.length) {
          showNotif('Imágenes importadas: '+(files.length-ignored.length)+' (ignoradas: '+ignored.length+')');
          console.warn('Imágenes ignoradas (sin clave en el naming map):', ignored);
        } else {
          showNotif('✅ '+files.length+' imágenes importadas');
        }
      }
    };
    reader.readAsDataURL(file);
  });
}

// Helper interno: escribe una imagen base64 en el sitio correcto de S según su clave.
function _writeImgToS(key, dataUrl) {
  if (key.startsWith('__noticia__')) {
    const idx = parseInt(key.slice('__noticia__'.length),10);
    if (!S.noticias) S.noticias = [];
    if (S.noticias[idx]) S.noticias[idx].photo = dataUrl;
    return;
  }
  if (key.startsWith('dp_'))    { if(!S.driverProfiles) S.driverProfiles={}; const id=key.slice(3); if(!S.driverProfiles[id]) S.driverProfiles[id]={}; S.driverProfiles[id].photoDataUrl=dataUrl; return; }
  if (key.startsWith('pb_'))    { if(!S.driverProfiles) S.driverProfiles={}; const id=key.slice(3); if(!S.driverProfiles[id]) S.driverProfiles[id]={}; S.driverProfiles[id].photoB=dataUrl; return; }
  if (key.startsWith('ti_'))    { if(!S.driverProfiles) S.driverProfiles={}; const id=key.slice(3); if(!S.driverProfiles[id]) S.driverProfiles[id]={}; S.driverProfiles[id].teamImgUrl=dataUrl; return; }
  if (key.startsWith('layout_')) { const id=key.slice(7); const r=(S.races||[]).find(r=>String(r.id)===id); if(r) r.layoutDataUrl=dataUrl; return; }
  if (key.startsWith('hem_'))    { const id=key.slice(4); const e=(S.hemeroteca||[]).find(e=>String(e.id)===id); if(e) e.img=dataUrl; return; }
  if (key.startsWith('flogo_'))  { if(!S.footerLogos) S.footerLogos=[]; S.footerLogos[parseInt(key.slice(6),10)]=dataUrl; return; }
  if (key.startsWith('coverImg_')){ if(!S.coverImages) S.coverImages={}; S.coverImages[key.slice(9)]=dataUrl; return; }
  if (key.startsWith('cover_'))  { if(!S.coverBgs) S.coverBgs={}; S.coverBgs[key.slice(6)]=dataUrl; return; }
  if (key.startsWith('logo_'))   { if(!S.logos) S.logos={}; S.logos[key.slice(5)]=dataUrl; return; }
}


