// ════════════════════════════════════════════════════════════════════════
// CAPA 3 · BUSINESS LOGIC
// ════════════════════════════════════════════════════════════════════════

function computeStandings() {
  // Memoized: recompute only when data changed (see Step 5).
  // NOTE: callers must treat the result as READ-ONLY.
  if (_standingsCacheV === _dataVersion && _standingsCache) return _standingsCache;
  const pts={}, prev={};
  S.drivers.forEach(d=>{ pts[d.id]=0; prev[d.id]=0; });
  S.races.forEach((race,idx) => {
  S.drivers.forEach(d => {
    const pos = race.results[d.id];
    const p = pos ? (S.pointsSystem[pos]||0) : 0;
    const fl = race.fastestLap===d.id ? 1 : 0;
    pts[d.id] += p + fl;
    if (idx < S.races.length-1) {
   const pp = pos ? (S.pointsSystem[pos]||0) : 0;
   prev[d.id] += pp + fl;
    }
  });
  });
  if (S.races.length >= 1) {
  S.drivers.forEach(d=>{ prev[d.id]=0; });
  S.races.slice(0,-1).forEach(race => {
    S.drivers.forEach(d=>{
   const pos=race.results[d.id];
   const p=pos?(S.pointsSystem[pos]||0):0;
   const fl=race.fastestLap===d.id?1:0;
   prev[d.id]+=p+fl;
    });
  });
  }
  // Build ascending-sorted finish positions per driver (DNF/no-result excluded).
  // Comparing two such arrays element-wise resolves: best result first,
  // then count of that result, then second-best, etc.
  const finishesAsc = (driverId, racesArr) => {
    const arr = [];
    racesArr.forEach(r => {
      const p = r.results?.[driverId];
      if (typeof p === 'number' && p > 0) arr.push(p);
    });
    arr.sort((a,b) => a-b);
    return arr;
  };
  const tiebreak = (a, b, racesArr) => {
    if (b.points !== a.points) return b.points - a.points;
    const fa = finishesAsc(a.id, racesArr);
    const fb = finishesAsc(b.id, racesArr);
    const len = Math.max(fa.length, fb.length);
    for (let i = 0; i < len; i++) {
      const va = fa[i], vb = fb[i];
      if (va === undefined) return 1;          // a has fewer scoring finishes → b ahead
      if (vb === undefined) return -1;
      if (va !== vb) return va - vb;           // lower position number wins
    }
    return 0;
  };
  const sorted = S.drivers.map(d=>({...d,points:pts[d.id]||0}))
  .sort((a,b)=>tiebreak(a,b,S.races));
  const prevSorted = S.drivers.map(d=>({...d,points:prev[d.id]||0}))
  .sort((a,b)=>tiebreak(a,b,S.races.slice(0,-1)));
  sorted.forEach((d,i)=>{
  d.currentPos=i+1;
  d.prevPos=prevSorted.findIndex(x=>x.id===d.id)+1;
  d.posDelta=d.prevPos-d.currentPos;
  });
  _standingsCache = sorted;
  _standingsCacheV = _dataVersion;
  return sorted;
}

function computeTeamStandings() {
  const teamMap = {};
  S.drivers.forEach(d => {
  if (!teamMap[d.team]) teamMap[d.team] = [];
  teamMap[d.team].push(d);
  });
  return Object.entries(teamMap).map(([teamKey, drivers]) => {
  let pts=0, wins=0, podiums=0, fastestLaps=0, poles=0, bestPos=99;
  let bestGpPts=0, bestGpName='—', bestGpRound=0;
  S.races.forEach(race => {
    let racePts=0;
    drivers.forEach(d => {
   const pos=race.results[d.id];
   if(pos){
     const p=(S.pointsSystem[pos]||0)+(race.fastestLap===d.id?1:0);
     pts+=p; racePts+=p;
     if(pos===1)wins++;
     if(pos<=3)podiums++;
     if(pos<bestPos)bestPos=pos;
   }
   if(race.fastestLap===d.id)fastestLaps++;
   if(race.pole===d.id)poles++;
    });
    if(racePts>bestGpPts){ bestGpPts=racePts; bestGpName=race.name; bestGpRound=race.round; }
  });
  return { teamKey, drivers, pts, wins, podiums, fastestLaps, poles,
        bestPos: bestPos===99?'—':bestPos, bestGpPts, bestGpName, bestGpRound };
  }).sort((a,b)=>b.pts-a.pts);
}

function standingsBeforeRace(raceIndex) {
  if(raceIndex <= 0) return S.drivers.map(d=>({...d,points:0}));
  const pts={};
  S.drivers.forEach(d=>pts[d.id]=0);
  S.races.slice(0, raceIndex).forEach(race=>{
  S.drivers.forEach(d=>{
    const pos=race.results?.[d.id];
    if(pos&&pos>0) pts[d.id]+=(S.pointsSystem[pos]||0)+(race.fastestLap===d.id?1:0);
    const sp=race.sprintResults?.[d.id];
    if(sp) pts[d.id]+=((S.sprintPointsSystem||getDefaultSprintPoints())[sp]||0);
  });
  });
  return S.drivers.map(d=>({...d,points:pts[d.id]})).sort((a,b)=>b.points-a.points);
}

function standingsAfterRace(raceIndex) {
  const pts={};
  S.drivers.forEach(d=>pts[d.id]=0);
  S.races.slice(0, raceIndex+1).forEach(race=>{
  S.drivers.forEach(d=>{
    const pos=race.results?.[d.id];
    if(pos&&pos>0) pts[d.id]+=(S.pointsSystem[pos]||0)+(race.fastestLap===d.id?1:0);
    const sp=race.sprintResults?.[d.id];
    if(sp) pts[d.id]+=((S.sprintPointsSystem||getDefaultSprintPoints())[sp]||0);
  });
  });
  return S.drivers.map(d=>({...d,points:pts[d.id]})).sort((a,b)=>b.points-a.points);
}

function computeStandingsAfterRace(raceIndex) {
  const pts = {};
  S.drivers.forEach(d => pts[d.id] = 0);
  S.races.slice(0, raceIndex + 1).forEach(race => {
  S.drivers.forEach(d => {
    const pos = race.results?.[d.id];
    if (pos) pts[d.id] += (S.pointsSystem[pos]||0) + (race.fastestLap===d.id?1:0);
  });
  });
  return S.drivers.map(d => ({...d, points: pts[d.id]})).sort((a,b) => b.points - a.points);
}

function driverStats(driverId) {
  let wins=0,podiums=0,fastestLaps=0,poles=0,totalPts=0,bestPos=99,totalRaces=0;
  S.races.forEach(race=>{
  const pos=race.results[driverId];
  if(pos !== undefined && pos !== null){
    totalRaces++;
    if(pos > 0) {
   const sp=race.sprintResults?.[driverId];
   const spts=sp?((S.sprintPointsSystem||getDefaultSprintPoints())[sp]||0):0;
   const p=(S.pointsSystem[pos]||0)+(race.fastestLap===driverId?1:0)+spts;
   totalPts+=p;
   if(pos===1)wins++;
   if(pos<=3)podiums++;
   if(pos<bestPos)bestPos=pos;
    }
  }
  if(race.fastestLap===driverId)fastestLaps++;
  if(race.pole===driverId)poles++;
  });
  // Consistency & streaks
  const finishes = S.races.filter(r => r.results?.[driverId] !== undefined);
  const dnfs = finishes.filter(r => r.results[driverId] === 0).length;
  const finishRate = finishes.length > 0 ? Math.round((finishes.length - dnfs) / finishes.length * 100) : 100;

  // Scoring streak (consecutive races with points)
  let scoringStreak = 0, maxScoringStreak = 0, currentStreak = 0;
  [...S.races].reverse().forEach((race, i) => {
    const pos = race.results?.[driverId];
    const pts = pos && pos > 0 ? (S.pointsSystem[pos]||0) : 0;
    if (i === 0) { if (pts > 0) scoringStreak = 1; }
  });
  S.races.forEach(race => {
    const pos = race.results?.[driverId];
    const pts = pos && pos > 0 ? (S.pointsSystem[pos]||0) : 0;
    if (pts > 0) { currentStreak++; if (currentStreak > maxScoringStreak) maxScoringStreak = currentStreak; }
    else currentStreak = 0;
  });

  // Win streak
  let maxWinStreak = 0, curWinStreak = 0;
  S.races.forEach(race => {
    if (race.results?.[driverId] === 1) { curWinStreak++; if (curWinStreak > maxWinStreak) maxWinStreak = curWinStreak; }
    else curWinStreak = 0;
  });

  return {wins,podiums,fastestLaps,poles,totalPts,bestPos:bestPos===99?'—':bestPos,totalRaces,
    dnfs,finishRate,maxScoringStreak,maxWinStreak};
}

//

function streakScore(driverId) {
  // Returns numeric score for sorting streak intensity (0 = not on streak)
  const raceResults = S.races
    .map(r => r.results?.[driverId] !== undefined
        ? (r.results[driverId] > 0
            ? (S.pointsSystem[r.results[driverId]]||0)+(r.fastestLap===driverId?1:0)
            : 0)
        : null)
    .filter(v => v !== null);
  if (raceResults.length < 3) return 0;
  const recent = raceResults.slice(-Math.min(3, raceResults.length));
  const n = recent.length;
  let wSum=0, wTot=0;
  recent.forEach((v,i)=>{ const w=i+1; wSum+=v*w; wTot+=w; });
  const wAvg = wSum/wTot;
  const xMean=(n-1)/2, yMean=wAvg;
  let num=0,den=0;
  recent.forEach((v,i)=>{ num+=(i-xMean)*(v-yMean); den+=(i-xMean)**2; });
  const slope = den?num/den:0;
  const last3 = raceResults.slice(-3);
  const last3Scored = last3.every(v=>v>0);
  const maxPts = Math.max(1,...Object.values(S.pointsSystem||{}));
  if(slope>0 && wAvg>=(maxPts*0.22) && last3Scored) return wAvg * slope;
  return 0;
}

function isOnStreak(driverId) {

  const raceResults = S.races
    .map(r => r.results?.[driverId] !== undefined
        ? (r.results[driverId] > 0
            ? (S.pointsSystem[r.results[driverId]]||0)+(r.fastestLap===driverId?1:0)
            : 0)
        : null)
    .filter(v => v !== null);
  if (raceResults.length < 3) return false;
  const recent = raceResults.slice(-Math.min(3, raceResults.length));
  const n = recent.length;
  // Weighted average (recent races count more)
  let wSum=0, wTot=0;
  recent.forEach((v,i)=>{ const w=i+1; wSum+=v*w; wTot+=w; });
  const wAvg = wSum/wTot;
  // Linear regression slope
  const xMean=(n-1)/2, yMean=wSum/wTot;
  let num=0,den=0;
  recent.forEach((v,i)=>{ num+=(i-xMean)*(v-yMean); den+=(i-xMean)**2; });
  const slope = den?num/den:0;
  // Last 3 must all have scored
  const last3 = raceResults.slice(-3);
  const last3Scored = last3.every(v=>v>0);
  const maxPts = Math.max(1,...Object.values(S.pointsSystem||{}));
  return slope>0 && wAvg>=(maxPts*0.22) && last3Scored;
}

function checkRecords(race) {
  const messages = [];
  const standings = computeStandings();
  S.drivers.forEach(d => {
  const pos = race.results?.[d.id];
  if (!pos) return;
  const isLeader = standings[0]?.id === d.id;
  const prevWins = S.races.slice(0,-1).filter(r => r.results?.[d.id] === 1).length;
  const newWin = pos === 1;
  if (newWin && prevWins === 0) messages.push(`🏆 ${d.name} — ¡Primera victoria del campeonato!`);
  else if (newWin) messages.push(`🏆 ${d.name} — Victoria nº ${prevWins + 1}`);
  if (race.fastestLap === d.id) {
    const prevFLs = S.races.slice(0,-1).filter(r => r.fastestLap === d.id).length;
    if (prevFLs === 0) messages.push(`⚡ ${d.name} — ¡Primera Vuelta Rápida!`);
  }
  if (race.pole === d.id) {
    const prevPoles = S.races.slice(0,-1).filter(r => r.pole === d.id).length;
    if (prevPoles === 0) messages.push(`🎯 ${d.name} — ¡Primera Pole Position!`);
  }
  });
  if (S.races.length >= 2) {
  const prevStandings = computeStandingsAfterRace(S.races.length - 2);
  const newLeaderId = standings[0]?.id;
  const prevLeaderId = prevStandings[0]?.id;
  if (newLeaderId && prevLeaderId && newLeaderId !== prevLeaderId) {
    const newLeader = S.drivers.find(d => d.id === newLeaderId);
    const prevLeaderD = S.drivers.find(d => d.id === prevLeaderId);
    if (newLeader) messages.push(`🔄 Nuevo líder: ${newLeader.name}${prevLeaderD?' → supera a '+prevLeaderD.name:''}`);
  }
  }
  if (messages.length > 0) {
  let i = 0;
  const showNext = () => {
    if (i >= messages.length) return;
    const n = document.getElementById('notif');
    if(!n) return;
    n.textContent = messages[i];
    n.className = 'notif record show';
    i++;
    setTimeout(() => {
   n.classList.remove('show');
   setTimeout(showNext, 500);
    }, 2800);
  };
  setTimeout(showNext, 400);
  }
}

function computeEvolutionData() {
  const pts = {};
  S.drivers.forEach(d => pts[d.id] = []);
  S.races.forEach(race => {
  S.drivers.forEach(d => {
    const prev = pts[d.id].length > 0 ? pts[d.id][pts[d.id].length - 1] : 0;
    const pos = race.results?.[d.id];
    const p = pos ? (S.pointsSystem[pos]||0) + (race.fastestLap===d.id?1:0) : 0;
    const sp = race.sprintResults?.[d.id];
    const spts = sp ? ((S.sprintPointsSystem||getDefaultSprintPoints())[sp]||0) : 0;
    pts[d.id].push(prev + p + spts);
  });
  });
  return pts;
}

function computePositionData() {
  const posData = {};
  S.drivers.forEach(d => posData[d.id] = []);
  S.races.forEach((_, raceIdx) => {
  const ptsAtRace = {};
  S.drivers.forEach(d => ptsAtRace[d.id] = 0);
  S.races.slice(0, raceIdx + 1).forEach(race => {
    S.drivers.forEach(d => {
   const pos = race.results?.[d.id];
   const p = pos ? (S.pointsSystem[pos]||0) + (race.fastestLap===d.id?1:0) : 0;
   const sp = race.sprintResults?.[d.id];
   const spts = sp ? ((S.sprintPointsSystem||getDefaultSprintPoints())[sp]||0) : 0;
   ptsAtRace[d.id] += p + spts;
    });
  });
  const sorted = S.drivers.slice().sort((a,b) => ptsAtRace[b.id] - ptsAtRace[a.id]);
  sorted.forEach((d, i) => posData[d.id].push(i + 1));
  });
  return posData;
}

function getTeamAccent(teamKey) {
  const accents={
  'team-mclaren':'#FF8000','team-ferrari':'#cc1717','team-redbull':'#161960',
  'team-mercedes':'#00D2BE','team-aston':'#0d645e','team-williams':'#0241ff',
  'team-alpine':'#0093CC','team-haas':'#B6BABD','team-kick':'#52E252',
  'team-racing':'#6692FF','team-custom':'#555'
  };
  return accents[teamKey]||'#555';
}

function _darken(hex) {
  // Mix hex color with 25% black to get a richer darker variant
  const r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
  const dr=Math.round(r*0.72), dg=Math.round(g*0.72), db=Math.round(b*0.72);
  return '#'+[dr,dg,db].map(v=>v.toString(16).padStart(2,'0')).join('');
}

function parseQualTime(str) {
  // Parse mm:ss.sss to seconds
  if(!str) return null;
  const m = str.match(/^(\d+):(\d{2})\.(\d{1,3})$/);
  if(!m) return null;
  return parseInt(m[1])*60 + parseInt(m[2]) + parseInt(m[3].padEnd(3,'0'))/1000;
}

function formatQualTime(secs) {
  if (secs === null || secs === undefined || isNaN(secs)) return '';
  const n = Number(secs);
  const mins = Math.floor(n / 60);
  const s = (n % 60).toFixed(3).padStart(6, '0');
  return mins + ':' + s;
}

function parseVideoUrl(url) {
  url = (url||'').trim();
  const ytM = url.match(/(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)[\w-]{11}/);
  if(ytM) { const id=url.match(/(?:v=|embed\/|youtu\.be\/)([\w-]{11})/)?.[1]; return {type:'youtube',ytId:id}; }
  const vmM = url.match(/vimeo\.com\/(?:video\/)?([0-9]+)/);
  if(vmM) return { type:'vimeo', vimeoId:vmM[1] };
  if(url.match(/\.(mp4|webm|ogg|mov)(\?|$)/i)||url.startsWith('http')) return { type:'direct', src:url };
  return null;
}

function getVidThumb(v) {
  if(v.type === 'youtube' && v.ytId) return `https://img.youtube.com/vi/${v.ytId}/hqdefault.jpg`;
  if(v.type === 'vimeo' && v.vimeoId) return `https://vumbnail.com/${v.vimeoId}.jpg`;
  return v.thumb || null;
}

function getVidEmbed(v) {
  if(v.type === 'youtube' && v.ytId) return `https://www.youtube.com/embed/${v.ytId}?autoplay=1`;
  if(v.type === 'vimeo' && v.vimeoId) return `https://player.vimeo.com/video/${v.vimeoId}?autoplay=1`;
  return v.src || null;
}

function getDefaultSprintPoints() {
  return {1:8,2:7,3:6,4:5,5:4,6:3,7:2,8:1};
}

function getCircuitBg(code) {
  const colors = FLAG_GRADIENTS[code?.toUpperCase()];
  if(!colors||colors.length<2) return 'var(--gray)';
  if(colors.length===2) return `linear-gradient(135deg, ${colors[0]}22 0%, ${colors[1]}22 100%)`;
  return `linear-gradient(135deg, ${colors[0]}22 0%, ${colors[1]}18 50%, ${colors[2]}22 100%)`;
}

function getCircuitHistory(race) {
  const code = (race.countryCode||race.flag||'').toUpperCase();
  const nameMap = {'AUSTRALIA':'AU','CHINA':'CN','JAPÓN':'JP','JAPON':'JP',
  'BAHREIN':'BH','BAHRAIN':'BH','ARABIA SAUDÍ':'SA','ARABIA SAUDI':'SA',
  'MIAMI':'US','ESTADOS UNIDOS':'US'};
  const country = (race.country||race.name||'').toUpperCase();
  for(const [k,v] of Object.entries(nameMap)){
  if(country.includes(k)) return S.circuitHistory?.[race.id] || CIRCUIT_HISTORY[v] || '';
  }
  return S.circuitHistory?.[race.id] || CIRCUIT_HISTORY[code] || '';
}


// _normalizeGpName — normaliza un nombre de GP para hacer match con CIRCUIT_DATA.
// Quita prefijos ("GP", "GRAN PREMIO DE", "Grand Prix of"...), tildes, paréntesis
// y caracteres no alfanuméricos. "GRAN PREMIO DE GRAN BRETAÑA" -> "granbretana".
function _normalizeGpName(name) {
  let s = (name || '').toString().toLowerCase()
    .replace(/[áàäâ]/g,'a').replace(/[éèëê]/g,'e').replace(/[íìïî]/g,'i')
    .replace(/[óòöô]/g,'o').replace(/[úùüû]/g,'u').replace(/ñ/g,'n');
  s = s.replace(/^gp\s+/, '')
       .replace(/^gran\s+premio\s+(de\s+|del\s+)?/, '')
       .replace(/^grand\s+prix\s+(de\s+|du\s+|of\s+)?/, '');
  s = s.replace(/\([^)]*\)/g, '').trim();
  s = s.replace(/[^a-z0-9]/g, '');
  return s;
}

// getCircuitData — devuelve los datos técnicos del circuito que corresponde
// a un GP (recibe un objeto con .name; vale un race o un gp del calendario).
// Busca primero por match directo; si falla, prueba aliases.
function getCircuitData(gpOrRace) {
  if (!gpOrRace || !gpOrRace.name) return null;
  const norm = _normalizeGpName(gpOrRace.name);
  if (CIRCUIT_DATA[norm]) return CIRCUIT_DATA[norm];
  for (const [, data] of Object.entries(CIRCUIT_DATA)) {
    if ((data.aliases || []).some(a => _normalizeGpName(a) === norm)) return data;
  }
  return null;
}

// ─────────────────────────────────────────────────────────────────────
// ALGORITMO DE CUOTAS WET365 — sub-paso 3
// Funciones puras: leen S y CIRCUIT_DATA, devuelven cuotas decimales.
// Diseñado para ser robusto a datos pocos/ruidosos (Laplace smoothing).
// ─────────────────────────────────────────────────────────────────────

// _pilotBetStats — agrega los counters relevantes para el algoritmo.
// Una sola pasada por S.races. Devuelve un objeto con todas las stats.
function _pilotBetStats(driverId) {
  let wins=0, seconds=0, thirds=0, poles=0, fastestLaps=0, dnfs=0, gpsParticipated=0;
  let qualyPosSum=0, qualyPosCount=0;
  let posChangeSum=0, posChangeCount=0;
  const winsByType   = { 'urbano':0, 'técnico':0, 'fácil':0 };
  const partsByType  = { 'urbano':0, 'técnico':0, 'fácil':0 };
  const resultsByType= { 'urbano':[], 'técnico':[], 'fácil':[] };  // posiciones (0 = DNF)
  const dnfsByType   = { 'urbano':0, 'técnico':0, 'fácil':0 };
  const qualyByType  = { 'urbano':[], 'técnico':[], 'fácil':[] };  // posiciones de qualy
  const posChangeByType = { 'urbano':[], 'técnico':[], 'fácil':[] };
  const weatherResults = [];          // posiciones en carreras Mixto / Lluvia
  const raceTypeById = {};            // race.id -> tipo de circuito

  (S.races || []).forEach(race => {
    const cd = getCircuitData(race);
    const ctype = cd && cd.circuitType;
    if (race.id != null && ctype) raceTypeById[race.id] = ctype;
    const pos = race.results ? race.results[driverId] : undefined;
    if (pos === undefined || pos === null) return;
    gpsParticipated++;
    if (ctype && partsByType[ctype] !== undefined) {
      partsByType[ctype]++;
      resultsByType[ctype].push(pos);
    }
    if (race.weather === 'Mixto' || race.weather === 'Lluvia') {
      weatherResults.push(pos);
    }
    if (pos === 0) {
      dnfs++;
      if (ctype && dnfsByType[ctype] !== undefined) dnfsByType[ctype]++;
    } else if (pos === 1) {
      wins++;
      if (ctype && winsByType[ctype] !== undefined) winsByType[ctype]++;
    } else if (pos === 2) {
      seconds++;
    } else if (pos === 3) {
      thirds++;
    }
    if (race.pole === driverId) poles++;
    if (race.fastestLap === driverId) fastestLaps++;

    const qPos = race.qualResults ? race.qualResults[driverId] : null;
    if (qPos && qPos > 0) {
      qualyPosSum += qPos; qualyPosCount++;
      if (ctype && qualyByType[ctype] !== undefined) qualyByType[ctype].push(qPos);
      if (pos > 0) {
        posChangeSum += (qPos - pos);
        posChangeCount++;
        if (ctype && posChangeByType[ctype] !== undefined) posChangeByType[ctype].push(qPos - pos);
      }
    }
  });

  // Sanciones: totales y por tipo de circuito (cruzando p.raceId con race.id).
  let penalties = 0;
  const penaltiesByType = { 'urbano':0, 'técnico':0, 'fácil':0 };
  (S.penalties || []).forEach(p => {
    if (p.driverId !== driverId) return;
    penalties++;
    const t = raceTypeById[p.raceId];
    if (t && penaltiesByType[t] !== undefined) penaltiesByType[t]++;
  });

  return {
    wins, seconds, thirds, poles, fastestLaps, dnfs, penalties, gpsParticipated,
    meanQualyPos:  qualyPosCount  > 0 ? qualyPosSum / qualyPosCount  : null,
    meanPosChange: posChangeCount > 0 ? posChangeSum / posChangeCount : 0,
    winsByType, partsByType, resultsByType, dnfsByType, qualyByType,
    posChangeByType, weatherResults, penaltiesByType,
  };
}

// _smoothedRate — Laplace smoothing: (count + prior*strength) / (gps + strength).
// Evita probabilidades 0 o muy ruidosas cuando hay pocas carreras.
//   prior:    probabilidad uniforme de referencia (típicamente 1/N_drivers)
//   strength: peso del prior — equivale a "tantas carreras virtuales con prior"
function _smoothedRate(count, gps, prior, strength) {
  if (strength == null) strength = 5;
  return (count + prior * strength) / (gps + strength);
}

// _streakBoost — factor multiplicativo basado en streakScore (1.0 a 1.5).
// streakScore devuelve > 0 cuando el piloto está en racha buena.
function _streakBoost(driverId) {
  // Factor de racha rehecho (sub-paso 5). Ya no es un interruptor binario:
  // combina NIVEL (cómo de buenos son los resultados recientes) y TENDENCIA
  // (si el piloto mejora). El dominador (gana siempre) recibe el boost máximo
  // aunque su pendiente sea 0, porque su NIVEL es máximo. Gradiente continuo.
  // Rango devuelto: 1.00 (sin datos / flojo) .. 1.60 (dominador en ascenso).
  const pts = [];
  (S.races || []).forEach(r => {
    const pos = r.results ? r.results[driverId] : undefined;
    if (pos === undefined || pos === null) return;
    if (pos > 0) {
      pts.push((S.pointsSystem[pos] || 0) + (r.fastestLap === driverId ? 1 : 0));
    } else {
      pts.push(0);   // DNF: 0 puntos
    }
  });
  if (pts.length < 2) return 1.0;   // mínimo 2 carreras para que el strike cuente
  const recent = pts.slice(-3);
  const n = recent.length;
  const maxPts = Math.max(1, ...Object.values(S.pointsSystem || {}));

  // NIVEL: media ponderada (lo reciente pesa más), normalizada a [0..1]
  let wSum = 0, wTot = 0;
  recent.forEach((v, i) => { const w = i + 1; wSum += v * w; wTot += w; });
  const level = Math.min(1, (wSum / wTot) / maxPts);

  // TENDENCIA: pendiente de regresión normalizada a [-1..1]
  let trend = 0;
  if (n >= 2) {
    const xMean = (n - 1) / 2;
    let num = 0, den = 0;
    recent.forEach((v, i) => { num += (i - xMean) * v; den += (i - xMean) * (i - xMean); });
    const slope = den ? num / den : 0;
    trend = Math.max(-1, Math.min(1, slope / (maxPts / 2)));
  }

  // El nivel domina (hasta +45%); la tendencia ascendente suma hasta +15%.
  return 1 + level * 0.45 + Math.max(0, trend) * 0.15;
}

// _scoresToOdds — normaliza scores a probabilidades y devuelve cuotas
// decimales aplicando el margen de la casa.
//   margin: vig de la casa (0.05 = 5%, cuotas un 5% más bajas que las justas)
function _scoresToOdds(scoresMap, margin) {
  if (margin == null) margin = 0.05;
  const entries = Object.entries(scoresMap);
  const total = entries.reduce((a, [,v]) => a + v, 0);
  const out = {};
  if (total <= 0) {
    const n = entries.length || 1;
    const fallback = Math.min(100, Math.max(1.05, (1 - margin) * n));
    entries.forEach(([id]) => { out[id] = fallback; });
    return out;
  }
  entries.forEach(([id, sc]) => {
    const p = sc / total;
    let odd = p > 0 ? (1 - margin) / p : 100;
    odd = Math.min(100, Math.max(1.05, odd));
    out[id] = Math.round(odd * 100) / 100;
  });
  return out;
}

// _probToOdd — convierte una probabilidad absoluta (no normalizada) en cuota.
function _probToOdd(p, margin) {
  if (margin == null) margin = 0.05;
  if (!p || p <= 0) return 100;
  let odd = (1 - margin) / p;
  return Math.round(Math.min(100, Math.max(1.05, odd)) * 100) / 100;
}

// computeAllOdds — núcleo del algoritmo. Devuelve TODAS las cuotas para el
// próximo GP, o null si no se pueden calcular.

// _observedSCLambda — histórico de Safety Car OBSERVADO en las carreras ya
// disputadas (S.races[i].safetyCarCount), ponderado por similitud de tipo de
// circuito con el próximo GP. Devuelve {observed, nObs} o null si no hay datos.
function _observedSCLambda(nextType) {
  let wSum = 0, scSum = 0, nObs = 0;
  (S.races || []).forEach(r => {
    if (r.safetyCarCount == null) return;
    const rcd = getCircuitData(r);
    const sameType = rcd && rcd.circuitType === nextType;
    const w = sameType ? 1.0 : 0.4;   // mismo tipo pesa más
    wSum += w;
    scSum += r.safetyCarCount * w;
    nObs++;
  });
  if (nObs === 0) return null;
  return { observed: scSum / wSum, nObs };
}

// _crtFactors — factores de influencia de los tiempos de CONTRARRELOJ del
// próximo GP (round). Devuelve { pole:{}, fl:{}, victory:{}, hasData, ... }.
//   - pole: influencia importante  -> exp(-gap / 0.4)
//   - fl:   influencia pequeña     -> exp(-0.3 * gap / 0.4)
//   - victory: influencia vía GAPS -> sólo cuenta si la diferencia entre los
//     dos mejores tiempos es significativa (relevancia 0 si <=0.1s, plena si
//     >=0.5s). exp(-relevancia * gap / 0.8).
// Si no hay tiempos (o menos de 2), todos los factores se omiten y el que
// los consume usa 1.0 -> las cuotas siguen funcionando sin CRT.
function _crtFactors(round) {
  const result = { pole: {}, fl: {}, victory: {}, hasData: false, relevance: 0, gap12: 0 };
  if (!S.timeTrials || !S.timeTrials[round]) return result;
  const times = S.timeTrials[round].times || {};
  const parsed = {};
  Object.entries(times).forEach(([did, str]) => {
    const secs = parseQualTime(str);
    if (secs != null) parsed[did] = secs;
  });
  const vals = Object.values(parsed);
  if (vals.length < 2) return result;     // hacen falta >=2 para tener gaps
  result.hasData = true;
  const sorted = vals.slice().sort((a, b) => a - b);
  const best = sorted[0];
  const worst = sorted[sorted.length - 1];
  const gap12 = sorted[1] - best;
  result.gap12 = gap12;
  // Relevancia: gradiente que arranca a 0,2 s de separación entre el 1.º y
  // el 2.º y satura a 0,7 s. Mide cuánto discrimina el contrarreloj; si el
  // campo está apretado, su influencia se atenúa hacia cero.
  const relevance = Math.max(0, Math.min(1, (gap12 - 0.2) / 0.5));
  result.relevance = relevance;
  // Factor base por normalización min-max de los tiempos (el más rápido al
  // tope superior, el más lento al inferior). Rangos por apuesta: la pole
  // es donde el ritmo a una vuelta más manda; la victoria, donde menos.
  // Un piloto SIN tiempo recibe el suelo del rango: la incertidumbre
  // penaliza, en vez de beneficiar como ocurría con el factor 1,00.
  const span = worst - best;
  const ranges = { pole: [0.80, 1.30], fl: [0.90, 1.15], victory: [0.93, 1.10] };
  ['pole', 'fl', 'victory'].forEach(bet => {
    const lo = ranges[bet][0], hi = ranges[bet][1];
    (S.drivers || []).forEach(d => {
      let base;
      if (parsed[d.id] != null) {
        const t = span > 1e-9 ? (parsed[d.id] - best) / span : 0;  // 0 = mejor, 1 = peor
        base = hi - t * (hi - lo);
      } else {
        base = lo;   // sin tiempo de contrarreloj: la incertidumbre penaliza
      }
      result[bet][d.id] = 1 + (base - 1) * relevance;  // intensidad modulada por la relevancia
    });
  });
  return result;
}

// _compressOdds — compresión de cuotas (sólo Ganador/Pole/Vuelta Rápida).
//   - techo 15: la curva satura asintóticamente en 15, ninguna cuota lo supera.
//   - progresiva: identidad cerca del piso, las cuotas altas se aplastan más
//     (más ganancia para la casa cuanto menor la probabilidad).
//   - de la 3ª cuota en adelante (ordenadas), redondeo a 1 decimal.
function _compressOdds(oddsMap) {
  const FLOOR = 1.05, CEIL = 15, SCALE = 14;
  const compress = (x) => {
    if (x <= FLOOR) return x;
    return FLOOR + (CEIL - FLOOR) * (1 - Math.exp(-(x - FLOOR) / SCALE));
  };
  const compressed = {};
  Object.entries(oddsMap).forEach(([id, odd]) => { compressed[id] = compress(odd); });
  // Ordenar por cuota ascendente: 1ª y 2ª con 2 decimales, resto con 1.
  const sorted = Object.entries(compressed).sort((a, b) => a[1] - b[1]);
  const out = {};
  sorted.forEach(([id, val], i) => {
    out[id] = (i < 2) ? Math.round(val * 100) / 100 : Math.round(val * 10) / 10;
  });
  return out;
}


// Para cada GP disputado con tiempos de contrarreloj Y resultados de qualy,
// compara la posición del piloto en el ranking de tiempos CRT con su posición
// real en qualy (ambos rankings calculados sobre el subconjunto de pilotos
// que tienen los dos datos). La desviación media se convierte en fiabilidad:
// desviación pequeña → fiable (su CRT predice bien su qualy).
// Suavizado: con pocos GP, la fiabilidad tiende a 0.5 (neutra).

// _posValue — valor de una posición de carrera según la tabla acordada:
// VICTORIA +10, 2º +6, 3º +4, 4º +1, 5º 0, 6º -1, 7º -2, 8º -3,
// 9º o peor (terminando) -4, ABANDONO (pos 0) -5.
function _posValue(pos) {
  if (pos === 0) return -5;          // abandono
  if (pos === 1) return 10;
  if (pos === 2) return 6;
  if (pos === 3) return 4;
  if (pos === 4) return 1;
  if (pos === 5) return 0;
  if (pos === 6) return -1;
  if (pos === 7) return -2;
  if (pos === 8) return -3;
  return -4;                          // 9º o peor, pero terminando
}

// _circuitSpecIndex — índice de especialización: suma de _posValue de cada
// resultado dividida entre el número de carreras. 0 si no hay carreras.
function _circuitSpecIndex(positions) {
  if (!positions || positions.length === 0) return 0;
  let sum = 0;
  positions.forEach(p => { sum += _posValue(p); });
  return sum / positions.length;
}

// _minMaxFactor — normaliza un mapa {id: valor} a factores en el rango
// [lo, hi]. El piloto con mayor valor recibe hi (o lo si invert=true), y el
// resto un valor proporcional. Si todos los valores son iguales, devuelve
// 1.0 para todos (neutro: no diferencia a nadie).
function _minMaxFactor(valueMap, lo, hi, invert) {
  const ids = Object.keys(valueMap);
  if (ids.length === 0) return {};
  const vals = ids.map(id => valueMap[id]);
  const mn = Math.min.apply(null, vals);
  const mx = Math.max.apply(null, vals);
  const out = {};
  if (mx - mn < 1e-9) {
    ids.forEach(id => { out[id] = 1.0; });
    return out;
  }
  ids.forEach(id => {
    let t = (valueMap[id] - mn) / (mx - mn);   // 0..1
    if (invert) t = 1 - t;
    out[id] = lo + t * (hi - lo);
  });
  return out;
}


// _absenceProb — probabilidad de que un piloto NO participe en el próximo GP.
// Combina la tasa global de ausencias con la tendencia reciente (media
// ponderada que da más peso a las últimas carreras): así distingue a quien
// faltaba al principio pero ya no, de quien empieza a ausentarse ahora.
function _absenceProb(driverId) {
  const races = (S.races || []).slice().sort((a, b) => a.round - b.round);
  if (races.length === 0) return 0;
  const log = races.map(r => {
    const pos = r.results ? r.results[driverId] : undefined;
    return (pos === undefined || pos === null) ? 1 : 0;   // 1 = ausente
  });
  const n = log.length;
  const global = log.reduce((a, b) => a + b, 0) / n;
  let wSum = 0, wTot = 0;
  log.forEach((v, i) => { const w = i + 1; wSum += v * w; wTot += w; });
  const tendencia = wTot > 0 ? wSum / wTot : 0;
  return 0.40 * global + 0.60 * tendencia;
}

// _absenceOdd — cuota de la apuesta AUSENCIA a partir de P(ausencia).
// Sobre la presencia (1 - P): cuota 1,00 si el piloto nunca participó
// (mínimo obligatorio) y 15,00 si participó siempre (techo). La curva
// mantiene la cuota muy cerca de 1,00 mientras la participación es baja
// y sólo la dispara hacia 15 con participación alta.
function _absenceOdd(pAbs) {
  const K = 5;
  const presencia = Math.max(0, Math.min(1, 1 - pAbs));
  const cuota = 1 + 14 * (Math.exp(K * presencia) - 1) / (Math.exp(K) - 1);
  return Math.max(1.00, Math.min(15, Math.round(cuota * 100) / 100));
}

