// ════ REGISTRO VIVO DE CUOTAS (sub-paso 15) ════
const ALGO_VERSION = '1.2';
const ODDSLOG_KEY = 'leala_v2_oddslog';
const _LOG_BETS = ['victory','pole','fastestLap','penalty','dnf',
                   'overtakeUp','overtakeDown','absence'];
let _oddsLog = [];

function loadOddsLog() {
  try {
    const s = localStorage.getItem(ODDSLOG_KEY);
    _oddsLog = s ? JSON.parse(s) : [];
  } catch (e) { _oddsLog = []; }
  if (!Array.isArray(_oddsLog)) _oddsLog = [];
}
function saveOddsLog() {
  try { localStorage.setItem(ODDSLOG_KEY, JSON.stringify(_oddsLog)); } catch (e) {}
}
// Siembra inicial con las 6 carreras de la biblioteca retrospectiva.
function seedOddsLog() {
  if (_oddsLog.length > 0) return;
  if (typeof SEED_ODDSLOG === 'undefined') return;
  _oddsLog = SEED_ODDSLOG.map(e => JSON.parse(JSON.stringify(e)));
  saveOddsLog();
}

// Extrae cuotas + probabilidades limpias del objeto de computeAllOdds.
function _snapshotFromOdds(o) {
  const odds = {}, probs = {};
  _LOG_BETS.forEach(b => {
    odds[b] = {}; probs[b] = {};
    (S.drivers || []).forEach(d => {
      odds[b][d.id] = (o[b] && o[b][d.id] != null) ? o[b][d.id] : null;
      const bd = (o.breakdown && o.breakdown[b]) ? o.breakdown[b][d.id] : null;
      probs[b][d.id] = bd ? bd.cleanProb : null;
    });
  });
  odds.safetyCar = { yes: o.safetyCar.yes, no: o.safetyCar.no };
  const scbd = o.breakdown ? o.breakdown.safetyCar : null;
  probs.safetyCar = {
    yes: (scbd && scbd.yes) ? scbd.yes.cleanProb : null,
    no: (scbd && scbd.no) ? scbd.no.cleanProb : null,
  };
  return { odds, probs };
}

// Deriva el resultado real de una carrera de S.races (y sus sanciones).
function _realFromRace(race) {
  const res = race.results || {}, qr = race.qualResults || {};
  let winner = null;
  const dnfs = [], up = [], down = [], present = {};
  Object.keys(res).forEach(k => {
    const pos = res[k], id = Number(k);
    present[id] = true;
    if (pos === 1) winner = id;
    if (pos === 0) dnfs.push(id);
    const qp = qr[k];
    if (qp && pos > 0) { if (pos < qp) up.push(id); else if (pos > qp) down.push(id); }
  });
  const absent = [];
  (S.drivers || []).forEach(d => { if (!present[d.id]) absent.push(d.id); });
  const penalized = (S.penalties || [])
    .filter(p => p.raceId === race.id).map(p => p.driverId);
  return { winner: winner, pole: race.pole != null ? race.pole : null,
           fl: race.fastestLap != null ? race.fastestLap : null,
           dnfs: dnfs, up: up, down: down, absent: absent, penalized: penalized,
           sc: (race.safetyCarCount || 0) > 0 };
}

// Brier de una entrada: media de las 9 apuestas. Las de rendimiento sobre
// un piloto ausente no se evalúan (la apuesta se anularía).
function _brierOfEntry(entry) {
  const race = (S.races || []).find(r => Number(r.round) === Number(entry.round));
  if (!race) return null;
  const real = _realFromRace(race);
  const probs = entry.probs || {};
  const dids = (S.drivers || []).map(d => d.id);
  const winSets = {
    victory: real.winner != null ? [real.winner] : [],
    pole: real.pole != null ? [real.pole] : [],
    fastestLap: real.fl != null ? [real.fl] : [],
    penalty: real.penalized, dnf: real.dnfs,
    overtakeUp: real.up, overtakeDown: real.down, absence: real.absent,
  };
  let sum = 0, n = 0;
  _LOG_BETS.forEach(bet => {
    const wins = winSets[bet] || [];
    const pool = (bet === 'absence')
      ? dids : dids.filter(d => real.absent.indexOf(d) < 0);
    if (!pool.length || !probs[bet]) return;
    let t = 0;
    pool.forEach(d => {
      const p = probs[bet][d] != null ? probs[bet][d] : 0;
      const y = wins.indexOf(d) >= 0 ? 1 : 0;
      t += (p - y) * (p - y);
    });
    sum += t / pool.length; n++;
  });
  if (probs.safetyCar && probs.safetyCar.yes != null) {
    const y = real.sc ? 1 : 0, p = probs.safetyCar.yes;
    sum += (p - y) * (p - y); n++;
  }
  return n ? sum / n : null;
}

// Archiva la foto de cuotas ANTES de incorporar la carrera al estado.
function archiveOddsSnapshot(raceData) {
  const gp = nextGP();
  if (!gp || Number(gp.round) !== Number(raceData.round)) return;
  if (_oddsLog.some(e => Number(e.round) === Number(raceData.round))) return;
  const o = computeAllOdds();
  if (!o) return;
  const snap = _snapshotFromOdds(o);
  _oddsLog.push({
    round: raceData.round, name: raceData.name,
    algoVersion: ALGO_VERSION, source: 'vivo',
    odds: snap.odds, probs: snap.probs,
  });
  _oddsLog.sort((a, b) => a.round - b.round);
  saveOddsLog();
}

// HTML de la sección de sólo lectura del registro (Bloque C, admin).
function oddsLogSectionHTML() {
  if (!_oddsLog || !_oddsLog.length) return '';
  const rows = _oddsLog
    .map(e => ({ e: e, brier: _brierOfEntry(e) }))
    .filter(r => r.brier != null);
  if (!rows.length) return '';
  const avg = rows.reduce((a, r) => a + r.brier, 0) / rows.length;
  const body = rows.map(r => `
    <tr>
      <td style="padding:6px 10px;color:#cfe;">R${r.e.round}</td>
      <td style="padding:6px 10px;color:#cfe;">${r.e.name}</td>
      <td style="padding:6px 10px;text-align:center;color:#8aa395;">v${r.e.algoVersion}</td>
      <td style="padding:6px 10px;text-align:center;color:#8aa395;">${r.e.source === 'vivo' ? 'registro' : 'biblioteca'}</td>
      <td style="padding:6px 10px;text-align:right;font-family:'Consolas',monospace;color:var(--gold);">${r.brier.toFixed(4)}</td>
    </tr>`).join('');
  return `
    <div class="admin-only" style="margin-top:22px;border-top:1px solid #2c4334;padding-top:16px;">
      <div style="font-family:'Russo One',sans-serif;font-size:13px;letter-spacing:2px;color:var(--gold);margin-bottom:4px;">
        REGISTRO DE CUOTAS · BRIER ACUMULADO
      </div>
      <div style="font-size:11px;color:#8aa395;margin-bottom:10px;line-height:1.6;">
        Foto de las cuotas emitidas antes de cada GP, contrastada con el resultado real.
        Brier medio: <b style="color:var(--gold);">${avg.toFixed(4)}</b> sobre ${rows.length} carrera(s).
        Cuanto más bajo, mejor predicción (0 = perfecto). Sólo lectura.
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <tr style="border-bottom:1px solid #2c4334;">
          <th style="padding:6px 10px;text-align:left;color:#8aa395;font-size:10px;letter-spacing:1px;">RONDA</th>
          <th style="padding:6px 10px;text-align:left;color:#8aa395;font-size:10px;letter-spacing:1px;">GRAN PREMIO</th>
          <th style="padding:6px 10px;text-align:center;color:#8aa395;font-size:10px;letter-spacing:1px;">VERSIÓN</th>
          <th style="padding:6px 10px;text-align:center;color:#8aa395;font-size:10px;letter-spacing:1px;">ORIGEN</th>
          <th style="padding:6px 10px;text-align:right;color:#8aa395;font-size:10px;letter-spacing:1px;">BRIER</th>
        </tr>
        ${body}
      </table>
    </div>`;
}

function computeAllOdds() {
  const gp = nextGP();
  if (!gp) return null;
  const cd = getCircuitData(gp);
  if (!cd) return null;
  const drivers = S.drivers || [];
  if (!drivers.length) return null;

  const N = drivers.length;
  const prior = 1 / N;
  const ctype = cd.circuitType;
  const nextGpObj = (S.calendario || []).find(g => Number(g.round) === Number(gp.round));
  const qualyType = (nextGpObj && nextGpObj.qualyType) ? nextGpObj.qualyType : null;
  let rainPct = cd.rainPct != null ? cd.rainPct : 0;
  if (nextGpObj && nextGpObj.rainPctManual != null) rainPct = nextGpObj.rainPctManual;
  const isRain = rainPct >= 70;
  const isMixed = rainPct >= 45 && rainPct < 70;
  const isAdverse = isRain || isMixed;

  const stats = {};
  drivers.forEach(d => { stats[d.id] = _pilotBetStats(d.id); });
  const crt = _crtFactors(gp.round);

  // Encogimiento hacia la media (sub-paso 9): media real observada del grupo
  // para un evento dado (éxitos totales / participaciones totales). Sustituye
  // al prior fijo en el suavizado de las tasas base.
  const groupMean = (metric) => {
    let c = 0, g = 0;
    drivers.forEach(d => {
      const s = stats[d.id];
      c += (s[metric] || 0);
      g += s.gpsParticipated;
    });
    return g > 0 ? c / g : 0;
  };

  // Factor de Incomparecencia (sub-paso 11): penaliza haber corrido pocas
  // carreras. 1,00 si se han corrido todas las disputadas; baja hasta 0,70.
  const totalGPs = (S.races || []).length;
  const incompFactor = (did) => {
    if (totalGPs <= 0) return 1.0;
    return 0.70 + (stats[did].gpsParticipated / totalGPs) * 0.30;
  };

  // En sucesos negativos (sanción, abandono, perder posiciones) la
  // incomparecencia penaliza al revés: menos rodaje = más riesgo. Se usa
  // el inverso, que va de 1,00 (participación plena) hacia arriba.
  const incompFactorNeg = (did) => 1 / incompFactor(did);

  const breakdown = { victory:{}, pole:{}, fastestLap:{}, penalty:{}, dnf:{},
                      overtakeUp:{}, overtakeDown:{}, safetyCar:{}, absence:{} };

  const finalizeBd = (bdMap, scores, rawOdds, finalOdds, isCompressed) => {
    const total = Object.values(scores).reduce((a, b) => a + b, 0);
    Object.keys(bdMap).forEach(id => {
      const sc = scores[id] || 0;
      const prob = total > 0 ? sc / total : 1 / N;
      bdMap[id].score = sc;
      bdMap[id].cleanProb = prob;
      bdMap[id].oddFair = prob > 0 ? 1 / prob : 100;
      bdMap[id].oddMargin = rawOdds[id];
      bdMap[id].oddFinal = finalOdds[id];
      bdMap[id].compressed = isCompressed;
    });
  };

  // ─── VICTORIA ────────────────────────────────────────────────────
  // Base = TasaVictorias + TasaSegundos×0.25 + TasaTerceros×0.10
  const victBase = {}, victBaseParts = {};
  const circuitSpecRaw = {}, weatherSpecRaw = {}, reliabRaw = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const gps = s.gpsParticipated;
    // Encogimiento hacia la media del grupo (sub-paso 10): cada tasa se
    // suaviza hacia la media real del campeonato. Sustituye al antiguo
    // valor fijo 0,050: un piloto con pocas (o ninguna) victoria queda
    // cerca de la media observada, no en un número inventado.
    const tVict = (s.wins    + groupMean('wins')    * 5) / (gps + 5);
    const tSeg  = (s.seconds + groupMean('seconds') * 5) / (gps + 5);
    const tTer  = (s.thirds  + groupMean('thirds')  * 5) / (gps + 5);
    victBase[d.id] = tVict + tSeg * 0.25 + tTer * 0.10;
    victBaseParts[d.id] = { tVict, tSeg, tTer };
    circuitSpecRaw[d.id] = _circuitSpecIndex(s.resultsByType[ctype] || []);
    weatherSpecRaw[d.id] = _circuitSpecIndex(s.weatherResults || []);
    reliabRaw[d.id] = gps > 0 ? 1 - s.dnfs / gps : 1;
  });
  // Factores normalizados al grupo
  const circuitSpecF = _minMaxFactor(circuitSpecRaw, 0.80, 1.30, false);
  const weatherSpecF = isAdverse ? _minMaxFactor(weatherSpecRaw, 0.85, 1.20, false) : null;
  const reliabF      = _minMaxFactor(reliabRaw, 0.95, 1.10, false);
  // Score SIN el factor meteo (para luego ordenar y aplicar la escala)
  const victComp = {}, victNoWeather = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    let parrillaF = 1.0;
    if (s.meanQualyPos != null) parrillaF = 1 + (1 - (s.meanQualyPos / N)) * 0.30;
    const streakF = _streakBoost(d.id);
    const crtF    = crt.hasData ? crt.victory[d.id] : 1.0;
    const wsF     = weatherSpecF ? weatherSpecF[d.id] : 1.0;
    victComp[d.id] = { parrillaF, streakF, crtF, wsF };
    victNoWeather[d.id] = victBase[d.id] * circuitSpecF[d.id] * wsF
                        * parrillaF * streakF * reliabF[d.id] * crtF
                        * incompFactor(d.id);
  });
  // Factor meteo progresivo: sólo en lluvia, por ranking de score sin meteo.
  const weatherProg = {};
  if (isRain) {
    const ranked = Object.entries(victNoWeather).sort((a, b) => b[1] - a[1]);
    const scale = [0.60, 0.70, 0.80, 0.85, 0.90, 0.95];
    ranked.forEach(([id], i) => { weatherProg[id] = i < scale.length ? scale[i] : 1.0; });
  } else {
    drivers.forEach(d => { weatherProg[d.id] = 1.0; });
  }
  const victoryScores = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const c = victComp[d.id];
    const bp = victBaseParts[d.id];
    const score = victNoWeather[d.id] * weatherProg[d.id];
    victoryScores[d.id] = score;
    const steps = [
      { label: 'Tasa de victorias', value: bp.tVict,
        note: `${s.wins} victoria(s) en ${s.gpsParticipated} GP · encogida hacia la media del grupo` },
      { label: '+ Tasa de 2º puestos (×0.25)', value: bp.tSeg * 0.25,
        note: `${s.seconds} segundo(s) puesto(s) · 4 equivalen a 1 victoria` },
      { label: '+ Tasa de 3º puestos (×0.10)', value: bp.tTer * 0.10,
        note: `${s.thirds} tercer(os) puesto(s)` },
      { label: '= Base combinada', value: victBase[d.id], note: 'suma de las tres tasas' },
      { label: '× Especialización en circuito', value: circuitSpecF[d.id],
        note: `índice de resultados en circuitos de tipo ${ctype} (rango 0.80–1.30)` },
    ];
    if (weatherSpecF) {
      steps.push({ label: '× Especialización en meteo', value: c.wsF,
        note: `rendimiento en carreras de Mixto/Lluvia (próximo GP ${isRain ? 'Lluvia' : 'Mixto'})` });
    }
    steps.push(
      { label: '× Parrilla media', value: c.parrillaF,
        note: s.meanQualyPos != null ? `clasifica ${s.meanQualyPos.toFixed(1)}º de media` : 'sin datos de qualy' },
      { label: '× Racha (strike)', value: c.streakF,
        note: c.streakF > 1.01 ? 'forma reciente al alza' : 'forma reciente neutra (o menos de 2 carreras)' },
      { label: '× Fiabilidad', value: reliabF[d.id],
        note: `${((reliabRaw[d.id]) * 100).toFixed(0)}% de carreras terminadas` },
      { label: '× Contrarreloj', value: c.crtF,
        note: c.crtF !== 1 ? 'gap en tiempos de contrarreloj' : 'sin datos de contrarreloj' },
      { label: '× Meteorología', value: weatherProg[d.id],
        note: isRain ? 'lluvia: escala progresiva que iguala probabilidades' : 'sin lluvia prevista' },
      { label: '× Incomparecencia', value: incompFactor(d.id),
        note: `${s.gpsParticipated} de ${totalGPs} carreras disputadas` }
    );
    breakdown.victory[d.id] = { factorSteps: steps };
  });
  const victoryRaw = _scoresToOdds(victoryScores, 0.05);
  const victory = _compressOdds(victoryRaw);
  finalizeBd(breakdown.victory, victoryScores, victoryRaw, victory, true);

  // ─── POLE ────────────────────────────────────────────────────────
  // Factor de relación con el tipo de circuito: posición media de qualy en
  // circuitos de ese tipo (si no hay, la media global del piloto).
  const poleCircRaw = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const arr = s.qualyByType[ctype] || [];
    if (arr.length > 0) {
      poleCircRaw[d.id] = arr.reduce((a, b) => a + b, 0) / arr.length;
    } else {
      poleCircRaw[d.id] = s.meanQualyPos != null ? s.meanQualyPos : (N + 1) / 2;
    }
  });
  const poleCircF = _minMaxFactor(poleCircRaw, 0.85, 1.20, true);  // mejor qualy → mayor factor

  const poleScores = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const base = _smoothedRate(s.poles, s.gpsParticipated, groupMean('poles'), 5);
    let qualyF = 1.0;
    if (s.meanQualyPos != null) qualyF = 1 + (1 - (s.meanQualyPos / N)) * 0.5;
    const crtF = crt.hasData ? crt.pole[d.id] : 1.0;
    const relNote = crt.hasData
      ? `contrarreloj · relevancia ${(crt.relevance * 100).toFixed(0)}%`
      : 'sin datos de contrarreloj';
    const streakF = _streakBoost(d.id);
    const score = base * qualyF * streakF * crtF * poleCircF[d.id] * incompFactor(d.id);
    poleScores[d.id] = score;
    breakdown.pole[d.id] = { factorSteps: [
      { label: 'Tasa base de poles', value: base,
        note: `${s.poles} pole(s) en ${s.gpsParticipated} GP · encogimiento hacia la media del grupo` },
      { label: '× Parrilla media', value: qualyF,
        note: s.meanQualyPos != null ? `clasifica ${s.meanQualyPos.toFixed(1)}º de media` : 'sin datos de qualy' },
      { label: '× Especialización en circuito', value: poleCircF[d.id],
        note: `rendimiento en qualy en circuitos de tipo ${ctype}` },
      { label: '× Racha (strike)', value: streakF,
        note: streakF > 1.01 ? 'forma reciente al alza' : 'forma reciente neutra' },
      { label: '× Contrarreloj', value: crtF, note: relNote },
      { label: '× Incomparecencia', value: incompFactor(d.id),
        note: `${s.gpsParticipated} de ${totalGPs} carreras disputadas` },
    ]};
  });
  // Modulación de la pole según el modo de clasificación.
  if (qualyType === '18 minutos' || qualyType === 'Sprint Qualifying') {
    // Clasificación con rodaje: el factor dispersa, reforzando al favorito.
    const poleExp = qualyType === '18 minutos' ? 1.35 : 1.20;
    Object.keys(poleScores).forEach(id => { poleScores[id] = Math.pow(poleScores[id], poleExp); });
    Object.keys(breakdown.pole).forEach(id => {
      breakdown.pole[id].factorSteps.push({
        label: `Dispersión (Qualy ${qualyType})`,
        value: poleExp, op: 'exp',
        note: 'clasificación con rodaje: refuerza al favorito',
      });
    });
  } else if (qualyType === '1 vuelta') {
    // Una sola vuelta es muy impredecible: encogimiento agresivo de las
    // probabilidades hacia la media (1/N). Las cuotas se agrupan.
    const POLE_SHRINK = 0.35;   // peso del dato propio; más bajo = agrupa más
    const total = Object.values(poleScores).reduce((a, b) => a + b, 0);
    if (total > 0) {
      const uniform = 1 / drivers.length;
      Object.keys(poleScores).forEach(id => {
        const p = poleScores[id] / total;
        poleScores[id] = POLE_SHRINK * p + (1 - POLE_SHRINK) * uniform;
      });
      Object.keys(breakdown.pole).forEach(id => {
        breakdown.pole[id].factorSteps.push({
          label: 'Encogimiento (Qualy 1 vuelta)',
          value: POLE_SHRINK, op: 'shrink',
          note: 'qualy a una vuelta: muy impredecible, agrupa las cuotas hacia la media',
        });
      });
    }
  }
  const poleRaw = _scoresToOdds(poleScores, 0.05);
  const pole = _compressOdds(poleRaw);
  finalizeBd(breakdown.pole, poleScores, poleRaw, pole, true);

  // ─── VUELTA RÁPIDA ───────────────────────────────────────────────
  const flScores = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const base = _smoothedRate(s.fastestLaps, s.gpsParticipated, groupMean('fastestLaps'), 5);
    let topF = 1.0;
    if (s.meanQualyPos != null) topF = 1 + (1 - (s.meanQualyPos / N)) * 0.2;
    const streakF = _streakBoost(d.id);
    const crtF = crt.hasData ? crt.fl[d.id] : 1.0;
    const score = base * topF * streakF * crtF * incompFactor(d.id);
    flScores[d.id] = score;
    breakdown.fastestLap[d.id] = { factorSteps: [
      { label: 'Tasa base de vueltas rápidas', value: base,
        note: `${s.fastestLaps} VR en ${s.gpsParticipated} GP · encogimiento hacia la media del grupo` },
      { label: '× Posición de carrera', value: topF,
        note: 'los pilotos que ruedan en cabeza tienden a marcar la VR' },
      { label: '× Racha (strike)', value: streakF,
        note: streakF > 1.01 ? 'forma reciente al alza' : 'forma reciente neutra' },
      { label: '× Contrarreloj', value: crtF,
        note: crtF !== 1 ? 'ritmo a una vuelta (influencia pequeña)' : 'sin datos de contrarreloj' },
      { label: '× Incomparecencia', value: incompFactor(d.id),
        note: `${s.gpsParticipated} de ${totalGPs} carreras disputadas` },
    ]};
  });
  const flRaw = _scoresToOdds(flScores, 0.06);
  const fastestLap = _compressOdds(flRaw);
  finalizeBd(breakdown.fastestLap, flScores, flRaw, fastestLap, true);

  // ─── SANCIÓN ─────────────────────────────────────────────────────
  let circuitDiffPen = 1.0;
  if (cd.numCorners) circuitDiffPen *= 1 + (cd.numCorners - 14) / 28;
  if (ctype === 'urbano') circuitDiffPen *= 1.3;
  if (cd.firstCornerDistM != null && cd.firstCornerDistM < 300) circuitDiffPen *= 1.2;
  const weatherPen = isRain ? 1.5 : (isMixed ? 1.2 : 1.0);
  // Factor de relación con el tipo de circuito: frecuencia de sanción del
  // piloto en circuitos de ese tipo (si no hay, su tasa global).
  const penCircRaw = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const partsT = s.partsByType[ctype] || 0;
    penCircRaw[d.id] = partsT > 0
      ? (s.penaltiesByType[ctype] || 0) / partsT
      : (s.gpsParticipated > 0 ? s.penalties / s.gpsParticipated : 0);
  });
  const penCircF = _minMaxFactor(penCircRaw, 0.85, 1.20, false);

  const penaltyScores = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const base = _smoothedRate(s.penalties, s.gpsParticipated, groupMean('penalties'), 5);
    const score = base * circuitDiffPen * weatherPen * penCircF[d.id] * incompFactorNeg(d.id);
    penaltyScores[d.id] = score;
    breakdown.penalty[d.id] = { factorSteps: [
      { label: 'Tasa base de sanciones', value: base,
        note: `${s.penalties} sanción(es) en ${s.gpsParticipated} GP · encogimiento hacia la media del grupo` },
      { label: '× Dificultad del circuito', value: circuitDiffPen,
        note: 'nº de curvas, trazado urbano y salida a 1ª curva' },
      { label: '× Especialización en circuito', value: penCircF[d.id],
        note: `frecuencia de sanción en circuitos de tipo ${ctype}` },
      { label: '× Meteorología', value: weatherPen,
        note: weatherPen > 1 ? 'lluvia/mixto: más sanciones' : 'seco' },
      { label: '× Incomparecencia', value: incompFactorNeg(d.id),
        note: `riesgo: ${s.gpsParticipated} de ${totalGPs} GP — menos rodaje, más exposición` },
    ]};
  });
  const penaltyRaw = _scoresToOdds(penaltyScores, 0.07);
  const penalty = penaltyRaw;
  finalizeBd(breakdown.penalty, penaltyScores, penaltyRaw, penalty, false);

  // ─── ABANDONO (DNF) ──────────────────────────────────────────────
  let dnfDiff = 1.0;
  if (cd.runoff && cd.runoff.length === 4) {
    dnfDiff *= 1 + ((cd.runoff[0] || 0) / 100) * 0.4;
  }
  if (cd.highSpeedCorners) dnfDiff *= 1 + (cd.highSpeedCorners / 25);
  if (cd.lowSpeedCorners != null && cd.numCorners) {
    dnfDiff *= 1 - (cd.lowSpeedCorners / cd.numCorners) * 0.4;
  }
  if (cd.avgSpeedKmh != null && cd.topSpeedKmh) {
    dnfDiff *= 1 + ((cd.topSpeedKmh - cd.avgSpeedKmh) / cd.topSpeedKmh) * 0.5;
  }
  const weatherDNF = isRain ? 1.6 : (isMixed ? 1.25 : 1.0);
  // Factor de relación con el tipo de circuito: frecuencia de DNF del piloto
  // en circuitos de ese tipo (si no hay, su tasa global).
  const dnfCircRaw = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const partsT = s.partsByType[ctype] || 0;
    dnfCircRaw[d.id] = partsT > 0
      ? (s.dnfsByType[ctype] || 0) / partsT
      : (s.gpsParticipated > 0 ? s.dnfs / s.gpsParticipated : 0);
  });
  const dnfCircF = _minMaxFactor(dnfCircRaw, 0.85, 1.20, false);

  const dnfScores = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const base = _smoothedRate(s.dnfs, s.gpsParticipated, groupMean('dnfs'), 5);
    const score = base * dnfDiff * weatherDNF * dnfCircF[d.id] * incompFactorNeg(d.id);
    dnfScores[d.id] = score;
    breakdown.dnf[d.id] = { factorSteps: [
      { label: 'Tasa base de abandonos', value: base,
        note: `${s.dnfs} DNF en ${s.gpsParticipated} GP · encogimiento hacia la media del grupo` },
      { label: '× Dificultad del circuito', value: dnfDiff,
        note: 'muros, curvas rápidas, ratio curvas lentas y brecha de velocidad' },
      { label: '× Especialización en circuito', value: dnfCircF[d.id],
        note: `frecuencia de abandono en circuitos de tipo ${ctype}` },
      { label: '× Meteorología', value: weatherDNF,
        note: weatherDNF > 1 ? 'lluvia/mixto: más abandonos' : 'seco' },
      { label: '× Incomparecencia', value: incompFactorNeg(d.id),
        note: `riesgo: ${s.gpsParticipated} de ${totalGPs} GP — menos rodaje, más exposición` },
    ]};
  });
  const dnfRaw = _scoresToOdds(dnfScores, 0.07);
  const dnf = dnfRaw;
  finalizeBd(breakdown.dnf, dnfScores, dnfRaw, dnf, false);

  // ─── SAFETY CAR (evento) ─────────────────────────────────────────
  let scBase = cd.historicalSC != null ? cd.historicalSC : 0.8;
  const obsSC = _observedSCLambda(ctype);
  let scBaseNote = `histórico del circuito: ${scBase}`;
  if (obsSC) {
    const wObs = obsSC.nObs / (obsSC.nObs + 5);
    scBase = (1 - wObs) * scBase + wObs * obsSC.observed;
    scBaseNote = `histórico mezclado con ${obsSC.nObs} carrera(s) observada(s)`;
  }
  let scLambda = scBase;
  if (isRain) scLambda *= 1.6;
  else if (isMixed) scLambda *= 1.3;
  if (cd.runoff && cd.runoff.length === 4) {
    scLambda *= 1 + (((cd.runoff[0] || 0) + (cd.runoff[1] || 0)) / 100) * 0.2;
  }
  if (ctype === 'urbano') scLambda *= 1.2;
  const pSCyes = 1 - Math.exp(-scLambda);
  const pSCno  = 1 - pSCyes;
  const safetyCar = {
    yes: _probToOdd(pSCyes, 0.06),
    no:  _probToOdd(pSCno,  0.06),
  };
  breakdown.safetyCar = {
    factorSteps: [
      { label: 'λ base de Safety Car', value: scBase, note: scBaseNote },
      { label: 'λ ajustada', value: scLambda, op: 'info', note: 'modulada por meteo, escapatorias y tipo de circuito' },
    ],
    yes: { cleanProb: pSCyes, oddFair: pSCyes > 0 ? 1 / pSCyes : 100, oddFinal: safetyCar.yes },
    no:  { cleanProb: pSCno,  oddFair: pSCno  > 0 ? 1 / pSCno  : 100, oddFinal: safetyCar.no },
  };

  // ─── ADELANTAMIENTOS (gana / pierde posiciones) ──────────────────
  let overtakeFavor = 1.0;
  if (cd.firstCornerDistM != null && cd.firstCornerDistM > 500) overtakeFavor *= 1.2;
  if (cd.avgSpeedKmh != null && cd.avgSpeedKmh > 220) overtakeFavor *= 1.15;
  if (ctype === 'urbano') overtakeFavor *= 0.6;
  if (ctype === 'fácil')  overtakeFavor *= 1.2;
  // Factor de relación con el tipo de circuito: cambio medio de posición del
  // piloto en circuitos de ese tipo (si no hay, su cambio medio global).
  const ovCircRaw = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const arr = s.posChangeByType[ctype] || [];
    ovCircRaw[d.id] = arr.length > 0
      ? arr.reduce((a, b) => a + b, 0) / arr.length
      : (s.meanPosChange || 0);
  });
  const ovUpCircF   = _minMaxFactor(ovCircRaw, 0.85, 1.20, false);  // gana más → factor alto
  const ovDownCircF = _minMaxFactor(ovCircRaw, 0.85, 1.20, true);   // gana más → pierde menos

  const overtakeUp = {};
  const overtakeDown = {};
  drivers.forEach(d => {
    const s = stats[d.id];
    const mpc = s.meanPosChange || 0;
    const incF = incompFactor(d.id);
    const incFneg = incompFactorNeg(d.id);
    let pUp   = (0.5 + mpc / (2 * N)) * overtakeFavor * ovUpCircF[d.id] * incF;
    let pDown = (0.5 - mpc / (2 * N)) / Math.max(0.5, overtakeFavor) * ovDownCircF[d.id] * incFneg;
    pUp   = Math.max(0.05, Math.min(0.9, pUp));
    pDown = Math.max(0.05, Math.min(0.9, pDown));
    overtakeUp[d.id]   = _probToOdd(pUp,   0.05);
    overtakeDown[d.id] = _probToOdd(pDown, 0.05);
    const mpcNote = `cambio medio de posición: ${mpc >= 0 ? '+' : ''}${mpc.toFixed(2)}`;
    breakdown.overtakeUp[d.id] = {
      factorSteps: [
        { label: 'Cambio medio de posición', value: mpc, note: mpcNote },
        { label: 'Factor circuito', value: overtakeFavor, note: 'facilidad de adelantamiento del trazado' },
        { label: 'Especialización en circuito', value: ovUpCircF[d.id],
          note: `cambio de posición en circuitos de tipo ${ctype}` },
        { label: 'Incomparecencia', value: incF,
          note: `${s.gpsParticipated} de ${totalGPs} carreras disputadas` },
      ],
      cleanProb: pUp, oddFair: pUp > 0 ? 1 / pUp : 100,
      oddMargin: overtakeUp[d.id], oddFinal: overtakeUp[d.id], compressed: false,
    };
    breakdown.overtakeDown[d.id] = {
      factorSteps: [
        { label: 'Cambio medio de posición', value: mpc, note: mpcNote },
        { label: 'Factor circuito', value: overtakeFavor, note: 'facilidad de adelantamiento del trazado' },
        { label: 'Especialización en circuito', value: ovDownCircF[d.id],
          note: `cambio de posición en circuitos de tipo ${ctype}` },
        { label: 'Incomparecencia', value: incFneg,
          note: `riesgo: ${s.gpsParticipated} de ${totalGPs} GP — menos rodaje, más exposición` },
      ],
      cleanProb: pDown, oddFair: pDown > 0 ? 1 / pDown : 100,
      oddMargin: overtakeDown[d.id], oddFinal: overtakeDown[d.id], compressed: false,
    };
  });


  // ─── AUSENCIA (no participar en el próximo GP) ───────────────────
  const absence = {};
  drivers.forEach(d => {
    const pAbs = _absenceProb(d.id);
    const odd = _absenceOdd(pAbs);
    absence[d.id] = odd;
    const races = (S.races || []);
    breakdown.absence[d.id] = {
      factorSteps: [
        { label: 'Carreras disputadas', value: races.length,
          note: `el piloto participó en ${stats[d.id].gpsParticipated}` },
        { label: 'P(ausencia) — tasa global', value: races.length
            ? (races.length - stats[d.id].gpsParticipated) / races.length : 0,
          op: 'info', note: 'ausencias / carreras disputadas' },
        { label: 'P(ausencia) combinada', value: pAbs,
          op: 'info', note: '40% tasa global + 60% tendencia reciente' },
      ],
      cleanProb: pAbs,
      oddFair: pAbs > 0 ? 1 / pAbs : 100,
      oddMargin: odd,
      oddFinal: odd,
      compressed: false,
    };
  });

  return {
    nextGp: {
      name: gp.name, round: gp.round, country: gp.country,
      flag: gp.flag, date: gp.date,
    },
    circuit: cd,
    crt: { hasData: crt.hasData, relevance: crt.relevance, gap12: crt.gap12 },
    qualyType: qualyType,
    victory, pole, fastestLap, penalty, dnf,
    safetyCar, overtakeUp, overtakeDown, absence,
    breakdown: breakdown,
  };
}



// nextGP — devuelve el próximo GP del calendario que aún NO se ha disputado.
// MATCH POR ROUND (no por nombre): cada race tiene .round, cada gp del calendario
// tiene .round; un GP está disputado si su round aparece en S.races.
// Esto es robusto a diferencias de formato de nombre ("GP AUSTRALIA" vs
// "GRAN PREMIO DE AUSTRALIA"). Mismo enfoque que renderCalendario.
function nextGP() {
  const cal = S.calendario || [];
  if (!cal.length) return null;
  const disputedRounds = new Set((S.races || [])
    .map(r => Number(r.round || 0))
    .filter(Boolean));
  return cal.find(g => {
    const rnd = Number(g.round || 0);
    return rnd && !disputedRounds.has(rnd);
  }) || null;
}



function getAllFonts() {
  const custom = Object.keys(S.customFonts||{});
  return [...BUILTIN_FONTS, ...custom];
}

function _isViewActive(name) {
  const el = document.getElementById('view-' + name);
  return el && el.classList.contains('active');
}

function validatePositions(prefix, containerSuffix) {
  const positions = {};
  const dupes = [];
  S.drivers.forEach(d => {
  const el = document.getElementById(`${prefix}${d.id}`);
  if (!el) return;
  const val = parseInt(el.value);
  if (!isNaN(val) && val > 0) {
    if (positions[val]) dupes.push(val);
    positions[val] = (positions[val] || 0) + 1;
  }
  });
  const warnId = `warn-${containerSuffix}`;
  let warn = document.getElementById(warnId);
  if (dupes.length > 0) {
  if (!warn) {
    warn = document.createElement('div');
    warn.id = warnId;
    warn.className = 'validation-warn';
    const container = document.getElementById(`${prefix.replace('-','')}-entry-list`) ||
                   document.getElementById('race-entry-list');
    if (container) container.after(warn);
  }
  const dupList = [...new Set(dupes)].join(', ');
  warn.innerHTML = `<div class="warn-title">⚠️ Aviso — posiciones duplicadas</div>Posición(es) asignadas a más de un piloto: <strong>P${dupList}</strong>. Si es deliberado, ignora este aviso.`;
  } else {
  if (warn) warn.remove();
  }
}


