// CAPA 4 · VIEWS / RENDER
// ════════════════════════════════════════════════════════════════════════


// ── Render-error fallback helper (Step 4A) ──────────────────────────
function _renderError(containerId, sectionName, err) {
  console.error(sectionName + ' render error:', err);
  if (!containerId) return;
  const _el = document.getElementById(containerId);
  if (!_el) return;
  _el.innerHTML =
    '<div style="padding:24px 16px;text-align:center;color:var(--red,#cc1717);' +
    'font-family:sans-serif;font-size:13px;line-height:1.5;">' +
    '\u26A0 No se pudo cargar esta secci\u00F3n.<br>' +
    '<span style="color:var(--muted,#888);font-size:12px;">' +
    'Revisa la consola para ver el detalle del error.</span></div>';
}

// ── Re-render memoization (Step 4B) ─────────────────────────────────
// _dataVersion is bumped on every data mutation (saveState / loadState).
// _memoRender returns false when neither the data version nor the given
// ephemeral signature changed since this view's last successful render.
function _memoRender(name, ephemeralSig) {
  const key = _dataVersion + '|' + (ephemeralSig == null ? '' : ephemeralSig);
  if (_renderState[name] === key) return false;
  _renderState[name] = key;
  return true;
}



function renderStandings() {
  try {
  if (!_memoRender('renderStandings', (_evoOpen?'1':'0')+(_summaryOpen?'1':'0'))) return;
  try {
  const titleEl = document.getElementById('champ-title-display');
  if(titleEl) titleEl.textContent = S.championshipTitle||'';
  const last = S.races[S.races.length-1];
  const lastGpEl = document.getElementById('last-gp-display');
  if(lastGpEl) lastGpEl.textContent = last ? last.name : '—';
  const fiaEl=document.getElementById('fia-logo-el');
  if(fiaEl){const _s=imgSrc('logo_fia')||S.logos?.fia;if(_s)fiaEl.innerHTML=`<img src="${_s}" style="width:104px;height:104px;object-fit:contain;">`;}
  const f1El=document.getElementById('f1-logo-el');
  if(f1El){const _s=imgSrc('logo_f1');if(_s)f1El.innerHTML=`<img src="${_s}" style="height:40px;object-fit:contain;">`;}
  // Update nav WARCA logo
  const navWarca = document.getElementById('nav-warca-logo');
  if(navWarca && (S.logos?.warca||imgSrc('logo_warca'))) {
    navWarca.innerHTML = `<img src="${imgSrc('logo_warca')||S.logos?.warca||''}" style="max-height:28px;max-width:80px;object-fit:contain;">`;
  }
  // nav-noticias-w is now a static PNG icon (no dynamic replacement needed)
  // Sync to teams view too
  const fiaElT=document.getElementById('fia-logo-el-teams');
  if(fiaElT && (S.logos?.fia||imgSrc('logo_fia'))) fiaElT.innerHTML=`<img src="${imgSrc('logo_fia')||S.logos?.fia||''}" style="width:104px;height:104px;object-fit:contain;">`;
  const penFiaEl=document.getElementById('pen-fia-logo');
  const _penFiaSrc = S.logos?.fia_pen || S.logos?.fia || imgSrc('logo_fia_pen') || imgSrc('logo_fia');
  if(penFiaEl && _penFiaSrc) penFiaEl.innerHTML=`<img src="${_penFiaSrc}" style="width:44px;height:44px;object-fit:contain;">`;
  const f1ElT=document.getElementById('f1-logo-el-teams');
  if(f1ElT){const _s=imgSrc('logo_f1');if(_s)f1ElT.innerHTML=`<img src="${_s}" style="height:40px;object-fit:contain;">`;}
  const champT=document.getElementById('champ-title-display-teams');
  if(champT) champT.textContent=S.championshipTitle||'';
  const warcaEl=document.getElementById('warca-logo-el');
  if(warcaEl && (S.logos?.warca||imgSrc('logo_warca'))) warcaEl.innerHTML=`<img src="${imgSrc('logo_warca')||S.logos?.warca||''}" style="max-height:54px;object-fit:contain;">`;
  const stEl=document.getElementById('standings-title-display');
  if(stEl && S.standingsTitle) stEl.innerHTML=S.standingsTitle.replace('\n','<br>');
  const legendPts=document.querySelector('.legend-pts');
  if(legendPts){
    let html='';
    for(let i=1;i<=10;i++){
   const p=S.pointsSystem[i]||0;
   if(p>0) html+=`<span>P${i}: ${p}pts</span>`;
    }
    html+=`<span style="color:var(--gold)">VR: +1pto</span>`;
    legendPts.innerHTML=html;
  }
  } catch(e) { console.error('renderStandings header error:', e); }
  const standings = computeStandings();
  const list = document.getElementById('driver-list');
  if(!list) return;
  list.innerHTML = '';
  // Only the driver(s) with the HIGHEST streak score get the fire effect
  // RULE: if that driver is LOSING positions (posDelta < 0), streak is vacant
  const _sScores = standings.map(d => streakScore(d.id));
  const _maxSS = Math.max(0, ..._sScores);
  const _candidates = _maxSS > 0
    ? standings.filter((d,i) => _sScores[i] === _maxSS)
    : [];
  // Discard candidates who are losing positions in the standings
  const _validCandidates = _candidates.filter(d => (d.posDelta || 0) >= 0);
  const streakWinners = new Set(_validCandidates.map(d => d.id));
  standings.forEach((driver,idx)=>{
  const isP1 = idx===0;
  const onStreak=streakWinners.has(driver.id);
  const row = document.createElement('div');
  row.className='driver-row'+(isP1?' p1':'')+(onStreak?' on-streak':'');
  row.addEventListener('click', function(e) {
    const action = e.target.closest('[data-action]');
    if (!action) { openProfile(driver.id); return; }
    const id = parseInt(action.dataset.id);
    if (action.dataset.action === 'badge') { e.stopPropagation(); uploadTeamBadge(id); }
    else if (action.dataset.action === 'photo') { e.stopPropagation(); uploadDriverPhoto(id); }
    else openProfile(driver.id);
  });
  let chipsHTML='';
  S.races.forEach(race=>{
    const pos=race.results[driver.id];
    const isPole=race.pole===driver.id;
    const isFL=race.fastestLap===driver.id;
    if(!pos){
   const flagImgBlank = race.countryCode ? `<img src="https://flagcdn.com/w40/${race.countryCode.toLowerCase()}.png" alt="${race.countryCode}">` : '';
   chipsHTML+=`<div class="chip-wrap"><span class="race-chip chip-none"><span class="tri-top"></span><span class="tri-bot"></span><span class="chip-num">—</span></span>${isP1?`<span class="chip-flag">${flagImgBlank}</span>`:''}</div>`;
   return;
    }
    let baseClass='chip-none';
    if(pos===1) baseClass='chip-p1';
    else if(pos===2) baseClass='chip-p2';
    else if(pos===3) baseClass='chip-p3';
    else if((S.pointsSystem[pos]||0)>0) baseClass='chip-pts';
    else baseClass='chip-out';
    const flClass=isFL?' has-fl':'';
    const poleClass=isPole?' has-pole':'';
    const flagImg = race.countryCode ? `<img src="https://flagcdn.com/w40/${race.countryCode.toLowerCase()}.png" alt="${race.countryCode}">` : '';
    chipsHTML+=`<div class="chip-wrap"><span class="race-chip ${baseClass}${flClass}${poleClass}"><span class="tri-top"></span><span class="tri-bot"></span><span class="chip-num">${pos>0?pos:'DNF'}</span></span>${isP1?`<span class="chip-flag">${flagImg}</span>`:''}</div>`;
  });
  const delta=driver.posDelta;
  const trendClass=delta>0?'up':delta<0?'down':'same';
  const trendArrow=delta>0?'▲':delta<0?'▼':'—';
  const trendDelta=delta!==0?Math.abs(delta):'';
  const _tiSrc=imgSrc('ti_'+driver.id);
  const teamImg=_tiSrc
    ?`<img src="${_tiSrc}" alt="${driver.team}">`
    :`<span style="padding:4px">${TEAM_NAMES[driver.team]||'?'}</span>`;
  const _dpSrc=imgSrc('dp_'+driver.id);
  const driverPhoto=_dpSrc
    ?`<img src="${_dpSrc}" alt="${driver.name}">`
    :`<span class="photo-hint">👤</span>`;
  row.innerHTML=`
    <div class="pos-num">${driver.currentPos}</div>
    <div class="team-bar">
   <div class="team-badge ${driver.team}" id="tbadge-${driver.id}" data-action="badge" data-id="${driver.id}" title="Clic para cambiar imagen de escudería">${teamImg}</div>
    </div>
    <div class="driver-photo-slot" data-action="photo" data-id="${driver.id}" title="Clic para añadir foto del piloto">
   ${driverPhoto}
    </div>
    <div class="d-info">
   <div class="d-name">${driver.name}</div>
   <div class="race-chips">${chipsHTML}</div>
    </div>
    <div class="fire-badge-empty"></div>
    <div class="trend-el ${trendClass}">
      <span class="arr">${trendArrow}</span>
      <span class="dlt">${trendDelta}</span>
    </div>
    <div class="pts-box">${driver.points}</div>
  `;
  row.style.animationDelay = (idx * 0.045) + 's';
  list.appendChild(row);
  });
  if (_evoOpen) requestAnimationFrame(renderEvolutionChart);
  if (_summaryOpen) renderSeasonSummary();

  } catch (_e) { delete _renderState['renderStandings']; _renderError('driver-list', 'renderStandings', _e); }
}

function renderStandingsIfActive() {
  if (_isViewActive('standings')) renderStandings();
}

function renderSeasonSummary() {
  try {
  const container = document.getElementById('season-summary-container');
  if (!container || !S.races.length) return;

  const standings = computeStandings();
  const leader = standings[0];
  const teamStandings = computeTeamStandings();
  const topTeam = teamStandings[0];

  // Most poles, most VR, most podiums
  const stats = S.drivers.map(d => driverStats(d.id));
  const mostPoles = stats.reduce((a,b,i) => b.poles > (stats[a]?.poles||0) ? i : a, 0);
  const mostFL = stats.reduce((a,b,i) => b.fastestLaps > (stats[a]?.fastestLaps||0) ? i : a, 0);
  const mostPodiums = stats.reduce((a,b,i) => b.podiums > (stats[a]?.podiums||0) ? i : a, 0);
  const mostDNF = stats.reduce((a,b,i) => (b.dnfs||0) > (stats[a]?.dnfs||0) ? i : a, 0);

  const d = (idx) => S.drivers[idx];
  const s = (idx) => stats[idx];

  // Highest single-race score
  let bestRacePts = 0, bestRaceDriver = null, bestRaceName = '';
  S.races.forEach(race => {
    S.drivers.forEach(drv => {
      const pos = race.results?.[drv.id];
      if (pos && pos > 0) {
        const pts = (S.pointsSystem[pos]||0) + (race.fastestLap===drv.id?1:0);
        if (pts > bestRacePts) { bestRacePts=pts; bestRaceDriver=drv; bestRaceName=race.name; }
      }
    });
  });

  // Leader changes
  let leaderChanges = 0, prevLeader = null;
  S.races.forEach((_, i) => {
    const s2 = computeStandingsAfterRace ? computeStandingsAfterRace(i) : null;
    if (s2 && s2[0]?.id !== prevLeader) { if(prevLeader!==null) leaderChanges++; prevLeader=s2[0]?.id; }
  });

  const accentColor = leader ? getTeamAccent(leader.team) : 'var(--red)';

  container.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:2px;margin-bottom:2px;">
      <div style="background:var(--gray2);padding:14px 16px;border-left:4px solid ${accentColor};">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.18em;text-transform:uppercase;color:var(--muted);margin-bottom:6px;">🏆 Líder del Campeonato</div>
        <div style="font-family:'Russo One',sans-serif;font-size:22px;color:var(--gold);">${leader?.name||'—'}</div>
        <div style="font-size:11px;color:var(--muted);margin-top:2px;">${leader?.points||0} puntos · ${s(standings.findIndex(x=>x.id===leader?.id))?.wins||0} victorias</div>
      </div>
      <div style="background:var(--gray2);padding:14px 16px;border-left:4px solid ${topTeam?getTeamAccent(topTeam.teamKey):'#555'};">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.18em;text-transform:uppercase;color:var(--muted);margin-bottom:6px;">🏎 Escudería Líder</div>
        <div style="font-family:'Russo One',sans-serif;font-size:22px;color:white;">${topTeam?(TEAM_NAMES_FULL[topTeam.teamKey]||topTeam.teamKey):'—'}</div>
        <div style="font-size:11px;color:var(--muted);margin-top:2px;">${topTeam?.pts||0} puntos constructor</div>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:2px;margin-bottom:2px;">
      <div style="background:var(--gray2);padding:12px 14px;text-align:center;">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:#0099ff;margin-bottom:4px;">Rey de la Pole</div>
        <div style="font-family:'Russo One',sans-serif;font-size:16px;">${d(mostPoles)?.name||'—'}</div>
        <div style="font-size:10px;color:#0099ff;margin-top:2px;">${s(mostPoles)?.poles||0} poles</div>
      </div>
      <div style="background:var(--gray2);padding:12px 14px;text-align:center;">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:#9900cc;margin-bottom:4px;">Rey VR</div>
        <div style="font-family:'Russo One',sans-serif;font-size:16px;">${d(mostFL)?.name||'—'}</div>
        <div style="font-size:10px;color:#9900cc;margin-top:2px;">${s(mostFL)?.fastestLaps||0} VR</div>
      </div>
      <div style="background:var(--gray2);padding:12px 14px;text-align:center;">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:#aaa;margin-bottom:4px;">Más Podios</div>
        <div style="font-family:'Russo One',sans-serif;font-size:16px;">${d(mostPodiums)?.name||'—'}</div>
        <div style="font-size:10px;color:#aaa;margin-top:2px;">${s(mostPodiums)?.podiums||0} podios</div>
      </div>
      <div style="background:var(--gray2);padding:12px 14px;text-align:center;">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:var(--red);margin-bottom:4px;">Más DNF</div>
        <div style="font-family:'Russo One',sans-serif;font-size:16px;">${d(mostDNF)?.name||'—'}</div>
        <div style="font-size:10px;color:var(--red);margin-top:2px;">${s(mostDNF)?.dnfs||0} abandonos</div>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:2px;">
      <div style="background:var(--gray2);padding:12px 16px;">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:var(--muted);margin-bottom:4px;">⚡ Mejor resultado en una carrera</div>
        <div style="font-family:'Russo One',sans-serif;font-size:18px;color:var(--gold);">${bestRaceDriver?.name||'—'} — +${bestRacePts}p</div>
        <div style="font-size:11px;color:var(--muted);margin-top:2px;">${bestRaceName}</div>
      </div>
      <div style="background:var(--gray2);padding:12px 16px;">
        <div style="font-size:9px;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:var(--muted);margin-bottom:4px;">Estadísticas generales</div>
        <div style="font-family:'Barlow Condensed',sans-serif;font-size:13px;font-weight:700;color:var(--text);">${S.races.length} GPs disputados · ${leaderChanges} cambios de líder</div>
        <div style="font-size:11px;color:var(--muted);margin-top:2px;">${S.drivers.length} pilotos · ${teamStandings.length} escuderías</div>
      </div>
    </div>
  `;

  } catch (_e) { _renderError('season-summary-container', 'renderSeasonSummary', _e); }
}

function renderEvolutionChart() {
  try {
  if (!S.races.length) return;
  const canvas = document.getElementById('evolution-chart');
  if (!canvas) return;
  const isPos = _evoMode === 'pos';
  const data = isPos ? computePositionData() : computeEvolutionData();
  const labels = S.races.map(r => {
    const cc = (r.countryCode||r.flag||'').toLowerCase().slice(0,2);
    // Use regional indicator letters (flag emoji from country code)
    if(cc && cc.length===2 && /^[a-z]{2}$/.test(cc)) {
      return String.fromCodePoint(
        0x1F1E6 + cc.charCodeAt(0) - 97,
        0x1F1E6 + cc.charCodeAt(1) - 97
      );
    }
    return r.name.replace('GRAN PREMIO DE ','').replace('GRAN PREMIO DEL ','').slice(0,8);
  });
  const standings = computeStandings();
  const n = S.drivers.length;
  const datasets = standings.map(driver => {
  const values = isPos ? data[driver.id] : [0, ...data[driver.id]];
  return {
    label: driver.name,
    data: values,
    borderColor: getTeamAccent(driver.team),
    backgroundColor: 'transparent',
    borderWidth: driver.currentPos === 1 ? 3 : 1.5,
    pointRadius: 3,
    pointHoverRadius: 5,
    tension: 0.3,
  };
  });
  const chartLabels = isPos ? labels : ['Inicio', ...labels];
  if (_evoChart) { _evoChart.destroy(); _evoChart = null; }
  _evoChart = new Chart(canvas, {
  type: 'line',
  data: { labels: chartLabels, datasets },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
   legend: { labels: { color:'#7A7A95', font:{ family:"'Barlow Condensed', sans-serif", size:11 }, boxWidth:16, padding:10 } },
   tooltip: { backgroundColor:'#111', titleColor:'#eee', bodyColor:'#aaa', borderColor:'#333', borderWidth:1 }
    },
    scales: {
   x: { ticks:{ color:'#555', font:{size:10} }, grid:{ color:'#1a1a1a' } },
   y: {
     ticks: { color:'#555', font:{size:10}, stepSize: isPos ? 1 : undefined },
     grid: { color:'#1a1a1a' },
     reverse: isPos,
     min: isPos ? 1 : undefined,
     max: isPos ? n : undefined,
     title: { display:true, text: isPos ? 'Posición' : 'Puntos', color:'#555', font:{size:10} }
   }
    }
  }
  });
  canvas.style.height = '260px';

  } catch (_e) { _renderError(null, 'renderEvolutionChart', _e); }
}
const _driverEvoMode = {}

function renderDriverEvolutionChart(driverId) {
  try {
  const canvas = document.getElementById(`driver-evo-${driverId}`);
  if (!canvas || !S.races.length) return;
  const mode = _driverEvoMode[driverId] || 'pos';
  const driver = S.drivers.find(d => d.id === driverId);
  const color = driver ? getTeamAccent(driver.team) : '#cc1717';
  const labels = S.races.map(r => r.name.replace('GRAN PREMIO DE ','').replace('GRAN PREMIO DEL ','').slice(0,10));
  let chartData, yConfig;
  if (mode === 'pts') {
  let cum = 0;
  chartData = S.races.map(race => {
    const pos = race.results?.[driverId];
    const pts = pos ? (S.pointsSystem[pos]||0) + (race.fastestLap===driverId?1:0) : 0;
    const sp = race.sprintResults?.[driverId];
    const spts = sp ? ((S.sprintPointsSystem||getDefaultSprintPoints())[sp]||0) : 0;
    cum += pts + spts;
    return cum;
  });
  yConfig = { ticks:{ color:'#555', font:{size:9} }, grid:{ color:'#1a1a1a' }, title:{ display:true, text:'Puntos', color:'#555', font:{size:9} } };
  } else {
  const posData = computePositionData();
  chartData = posData[driverId] || [];
  const n = S.drivers.length;
  yConfig = {
    ticks:{ color:'#555', font:{size:9}, stepSize:1 }, grid:{ color:'#1a1a1a' },
    reverse: true, min:1, max:n,
    title:{ display:true, text:'Posición', color:'#555', font:{size:9} }
  };
  }
  const existing = Chart.getChart(canvas);
  if (existing) existing.destroy();
  new Chart(canvas, {
  type: 'line',
  data: {
    labels,
    datasets: [{
   label: mode === 'pts' ? 'Puntos acumulados' : 'Posición en campeonato',
   data: chartData,
   borderColor: color,
   backgroundColor: color + '22',
   fill: mode === 'pts',
   borderWidth: 2,
   pointRadius: 4,
   tension: 0.3,
    }]
  },
  options: {
    responsive: true,
    plugins: {
   legend: { display:false },
   tooltip: { backgroundColor:'#111', titleColor:'#eee', bodyColor:'#aaa', borderColor:'#333', borderWidth:1 }
    },
    scales: {
   x: { ticks:{ color:'#555', font:{size:9} }, grid:{ color:'#1a1a1a' } },
   y: yConfig
    }
  }
  });

  } catch (_e) { _renderError(null, 'renderDriverEvolutionChart', _e); }
}

function renderTeams() {
  try {
  if (!_memoRender('renderTeams', '')) return;
  const el=document.getElementById('teams-standings-el');
  const msg=document.getElementById('no-teams-msg');
  el.innerHTML='';
  if(!S.drivers.length){ msg.style.display='block'; return; }
  msg.style.display='none';
  const standings=computeTeamStandings();
  const grid=document.createElement('div');
  grid.className='teams-grid';
  standings.forEach((team,idx)=>{
  const rank=idx+1;
  const driverNames=team.drivers.map(d=>d.name).join(' · ');
  const statParts=[];
  if(team.wins>0)        statParts.push(`<span class="stat-v">${team.wins}V</span>`);
  if(team.podiums>0)     statParts.push(`<span class="stat-p">${team.podiums}P</span>`);
  if(team.fastestLaps>0) statParts.push(`<span class="stat-vr">${team.fastestLaps}VR</span>`);
  if(team.poles>0)       statParts.push(`<span class="stat-pp">${team.poles}PP</span>`);
  const statsLine=statParts.length>0?statParts.join(' / '):`<span style="color:rgba(255,255,255,0.3)">—</span>`;
  const storedLogo=(S.logos&&S.logos[`teamLogo_${team.teamKey}`])||imgSrc('logo_teamLogo_'+team.teamKey);
  const logoThumb=storedLogo
    ?`<div class="team-logo-corner" data-action="upload"><img src="${storedLogo}" alt="logo"></div>`
    :`<div class="team-logo-corner team-logo-corner-empty" data-action="upload">+</div>`;
  const card=document.createElement('div');
  card.className='team-card'+(rank===1?' rank1':'');
  card.innerHTML=`
    <div class="team-card-logo" data-action="navigate">
   <div class="team-badge ${team.teamKey}" style="position:absolute;inset:0;border-radius:0;"></div>
   <div class="team-card-rank">${rank}</div>
   ${logoThumb}
    </div>
    <div class="team-card-bottom" data-action="navigate">
   <div class="team-card-left">
     <div class="team-card-name-row">
       <span class="team-card-name">${TEAM_NAMES_FULL[team.teamKey]||team.teamKey}</span>
       <span class="team-card-name-sep">/</span>
       <span class="team-card-drivers">${driverNames}</span>
     </div>
     <div class="team-card-stats">${statsLine}</div>
   </div>
   <div class="team-card-pts-right">${team.pts}pts</div>
    </div>
  `;
  const thisTeamKey = team.teamKey;
  card.addEventListener('click', function(e) {
    const action = e.target.closest('[data-action]');
    if (!action) return;
    if (action.dataset.action === 'upload') {
   e.stopPropagation();
   uploadTeamLogo(thisTeamKey);
    } else {
   openTeam(thisTeamKey);
    }
  });
  grid.appendChild(card);
  });
  el.appendChild(grid);

  } catch (_e) { delete _renderState['renderTeams']; _renderError('teams-standings-el', 'renderTeams', _e); }
}

