function renderCalendario() {
  try {
  if (!_memoRender('renderCalendario', '')) return;
  const el = document.getElementById('calendario-list');
  if(!el) return;
  const cal = S.calendario||[];
  if(!cal.length) {
    el.innerHTML='<div style="color:var(--muted);font-size:14px;padding:20px 0;">No hay GPs en el calendario. Pulsa "+ Añadir GP" para comenzar.</div>';
    return;
  }
  const now = new Date().toISOString().slice(0,10);
  // Build set of disputed rounds + country codes from S.races so a GP
  // marked as "celebrated" gets treated as past even if its date is still in the future.
  const disputedRounds = new Set((S.races||[]).map(r=>Number(r.round||0)).filter(Boolean));
  const isGpDisputed = (gp) => {
    const rnd = Number(gp.round||0);
    return rnd ? disputedRounds.has(rnd) : false;
  };
  el.innerHTML = cal.map((gp,i) => {
    const isPast = isGpDisputed(gp);
    const isNext = !isPast && cal.findIndex(g => !isGpDisputed(g)) === i;
    const dateStr = gp.date ? new Date(gp.date+'T00:00:00').toLocaleDateString('es-ES',{day:'2-digit',month:'short',year:'numeric'}) : '—';
    const _calSlug=(gp.country||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');
    const _calCC=(gp.flag||'').toLowerCase();
    const _calEmoji=_calCC.length===2?String.fromCodePoint(..._calCC.split('').map(c=>0x1F1E6+c.charCodeAt(0)-97)):'🏁';
    const _calUserImg=(S.logos&&(S.logos['flag_'+_calSlug]||S.logos['flag_'+_calCC]))||null;
    const roundLabel = `R${gp.round||i+1}`;
    const calClick = (isPast || isNext) ? `onclick="calNavigateToCircuit('${(gp.flag||'').toLowerCase().slice(0,2)}', '${(gp.name||'').replace(/'/g,"&#39;")}', ${gp.round||i+1})"` : '';
    const cursorStyle = (isPast || isNext) ? 'cursor:pointer;' : '';
    return `<div ${calClick} style="display:flex;height:64px;margin-bottom:5px;overflow:hidden;opacity:${isPast?'0.5':'1'};position:relative;border-radius:6px;${cursorStyle}" class="cal-band-row">
      <!-- Round number -->
      <div class="cal-round" style="width:46px;background:#111;display:flex;align-items:center;justify-content:center;flex-shrink:0;border-right:1px solid #222;">
        <span style="font-family:'Russo One',sans-serif;font-size:13px;color:${isNext?'var(--gold)':'var(--muted)'};letter-spacing:0.04em;">${roundLabel}</span>
      </div>
      <!-- Flag full height -->
      <div class="cal-flag" style="width:90px;flex-shrink:0;overflow:hidden;position:relative;cursor:pointer;" onclick="event.stopPropagation();uploadFlag('${gp.country||''}','${gp.flag||''}')" title="Clic para subir bandera">
        ${_calSlug ? `<div style="position:relative;width:100%;height:100%;"><span style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:30px;line-height:1;">${_calEmoji}</span><img loading="lazy" src="${_calUserImg||('assets/flags/'+_calCC+'_flag.webp')}" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;background:#0a0a0a;" onerror="if(this.src.indexOf('data:')===0){return;}if(!this.dataset.fb){this.dataset.fb=&quot;1&quot;;this.src='assets/flags/${_calCC}-sq_flag.webp';}else{this.remove();}"></div>` : '<div style="width:100%;height:100%;background:#222;display:flex;align-items:center;justify-content:center;font-size:24px;">🏁</div>'}
      </div>
      <!-- GP info -->
      <div class="cal-info" style="flex:1;padding:0 14px;display:flex;flex-direction:column;justify-content:center;gap:2px;background:${isNext?'var(--gray2)':'var(--gray)'};min-width:0;">
        <div class="cal-info-name" style="font-family:'Russo One',sans-serif;font-size:15px;text-transform:uppercase;color:${isNext?'white':'var(--text)'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${gp.name}</div>
        <div class="cal-info-date" style="font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${gp.country||''}${gp.country&&gp.date?' · ':''}${dateStr}</div>
      </div>
      <!-- PRÓXIMO GP: wide gold bar with vertical text, text color = band bg -->
      <div class="cal-next-bar" style="width:22px;flex-shrink:0;background:${isNext?'var(--gold)':'transparent'};border-radius:0 6px 6px 0;display:flex;align-items:center;justify-content:center;">
        ${isNext ? `<span style="font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:8px;letter-spacing:0.15em;text-transform:uppercase;writing-mode:vertical-rl;transform:rotate(180deg);white-space:nowrap;color:var(--black);">PRÓXIMO GP</span>` : ''}
      </div>
      <!-- Admin buttons -->
      <div class="admin-only" style="display:flex;flex-direction:column;border-left:1px solid #222;flex-shrink:0;">
        <button onclick="openAddGP(${i})" style="flex:1;background:none;border:none;border-bottom:1px solid #222;color:var(--muted);padding:0 10px;cursor:pointer;font-size:11px;" title="Editar">✏️</button>
        <button onclick="deleteGP(${i})" style="flex:1;background:none;border:none;color:var(--red);padding:0 10px;cursor:pointer;font-size:11px;" title="Eliminar">✕</button>
      </div>
    </div>`;
  }).join('');

  } catch (_e) { delete _renderState['renderCalendario']; _renderError('calendario-list', 'renderCalendario', _e); }
}

