function renderCircuits() {
  try {
  if (!_memoRender('renderCircuits', '')) return;
  const grid=document.getElementById('circuit-grid-el');
  const msg=document.getElementById('no-circuits-msg');
  grid.innerHTML='';

  // Helper para construir una tarjeta (válido para race disputada y para
  // el próximo GP, que usa datos del calendario).
  const makeCard = (data) => {
    const card = document.createElement('div');
    card.className = 'circuit-card' + (data.isNextGp ? ' next-gp' : '');
    card.onclick = () => openCircuit(data.openKey);
    const flagEl = data.flag
      ? `<img src="https://flagcdn.com/w80/${data.flag.toLowerCase()}.png" style="width:52px;height:34px;object-fit:cover;border-radius:2px;display:block;">`
      : `<span style="font-size:32px">${data.fallbackFlag || '🏁'}</span>`;
    const shortName = (data.name || '')
      .replace('GRAN PREMIO DE ', 'GP ')
      .replace('GRAN PREMIO DEL ', 'GP ')
      .replace('Gran Premio de ', 'GP ');
    card.innerHTML = `
      <div style="padding:20px 16px 8px">${flagEl}</div>
      <div class="circuit-card-info">
        <div class="circuit-card-round">Ronda ${data.round}</div>
        <div class="circuit-card-name">${shortName}</div>
      </div>
      ${data.isNextGp ? '<div class="next-gp-band"><span>PRÓXIMO GP</span></div>' : ''}`;
    return card;
  };

  // 1) GPs ya disputados
  (S.races || []).forEach(race => {
    grid.appendChild(makeCard({
      isNextGp: false,
      openKey: race.id,
      name: race.name,
      round: race.round,
      flag: race.countryCode,
      fallbackFlag: race.flag,
    }));
  });

  // 2) Próximo GP (si lo hay) como tarjeta con banda dorada
  const nxt = nextGP();
  if (nxt) {
    grid.appendChild(makeCard({
      isNextGp: true,
      openKey: 'next-' + (nxt.round || 0),
      name: nxt.name,
      round: nxt.round,
      flag: nxt.flag,
      fallbackFlag: nxt.flag,
    }));
  }

  // Mensaje "sin circuitos" sólo si NO hay nada de nada
  if (!S.races.length && !nxt) { msg.style.display = 'block'; }
  else { msg.style.display = 'none'; }

  } catch (_e) { delete _renderState['renderCircuits']; _renderError('circuit-grid-el', 'renderCircuits', _e); }
}
