function populateDuelSelects() {
  const sorted = [...S.drivers].sort((a, b) => {
  const ta = TEAM_NAMES_FULL[a.team]||a.team;
  const tb = TEAM_NAMES_FULL[b.team]||b.team;
  if (ta !== tb) return ta.localeCompare(tb);
  return a.name.localeCompare(b.name);
  });
  ['a','b'].forEach(side => {
  const sel = document.getElementById(`duel-select-${side}`);
  if (!sel) return;
  const current = sel.value;
  sel.innerHTML = '<option value="">— Seleccionar —</option>';
  sorted.forEach(d => {
    const opt = document.createElement('option');
    opt.value = d.id;
    opt.textContent = `${d.name} (${TEAM_NAMES_FULL[d.team]||d.team})`;
    sel.appendChild(opt);
  });
  if (current) sel.value = current;
  });
}

function renderPenaltiesPublic() {
  try {
  if (!_memoRender('renderPenaltiesPublic', '')) return;
  const el = document.getElementById('penalties-public-list');
  if(!el) return;
  // FIA logo rendered inline per card
  const pens = [...(S.penalties||[])].reverse();
  if(!pens.length) {
    el.innerHTML = '<div class="pen-empty">No hay sanciones registradas.</div>';
    return;
  }
  // Group by driverId + raceId
  const groups = [];
  const seen = new Map();
  pens.forEach(p => {
    const key = `${p.driverId}_${p.raceId}`;
    if (!seen.has(key)) { seen.set(key, groups.length); groups.push({ key, driverId:p.driverId, raceId:p.raceId, items:[] }); }
    groups[seen.get(key)].items.push(p);
  });
  el.innerHTML = groups.map(g => {
    const race = S.races.find(r=>r.id===g.raceId);
    const driver = S.drivers.find(d=>d.id===g.driverId);
    const teamName = driver ? (TEAM_NAMES_FULL[driver.team]||driver.team) : '—';
    const teamAccent = driver ? getTeamAccent(driver.team) : '#555';
    const cc = (race?.countryCode||race?.flag||'').toLowerCase().slice(0,2);
    const flagUrl = cc ? `https://flagcdn.com/w80/${cc}.png` : '';
    const gpName = race?.name?.replace('GRAN PREMIO DE ','').replace('GRAN PREMIO DEL ','') || '—';
    const rowsHtml = g.items.map((p,i) => `
      <div style="display:grid;grid-template-columns:1fr 1fr 2fr;border-top:1px solid var(--border);">
        <div class="pen-card-detail" style="${i===0?'':'border-top:none;'}">
          <div class="pen-card-sanction">${p.sanction||'—'}</div>
          <div class="pen-card-type-text">${p.type||'—'}</div>
        </div>
        <div class="pen-card-note" style="grid-column:2/4;">${p.note||'—'}</div>
      </div>`).join('');
    return `<div class="pen-card">
      <div class="pen-card-top-bar" style="display:flex;padding:0;overflow:hidden;height:auto;min-height:64px;align-items:stretch;">
        <!-- Flag full height -->
        <div style="width:90px;flex-shrink:0;overflow:hidden;position:relative;">
          ${flagUrl ? `<img src="${flagUrl}" style="width:100%;height:100%;object-fit:cover;display:block;">` : '<div style="width:100%;height:100%;background:#333;"></div>'}
        </div>
        <!-- GP name + driver -->
        <div style="flex:1;padding:10px 14px;display:flex;flex-direction:column;justify-content:center;gap:3px;">
          <div style="font-family:'Barlow Condensed',sans-serif;font-size:10px;font-weight:700;letter-spacing:0.16em;text-transform:uppercase;color:rgba(255,255,255,0.65);">SANCIÓN OFICIAL · ${gpName}</div>
          <div style="font-family:'Russo One',sans-serif;font-size:17px;text-transform:uppercase;color:white;line-height:1;">${driver?.name||'—'}</div>
          <div style="font-family:'Barlow Condensed',sans-serif;font-size:11px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:${teamAccent};">${teamName}</div>
        </div>
        <div class="pen-fia-logo-slot fia-logo-el" onclick="uploadPenFiaLogo()" title="Click para cambiar logo FIA" style="width:52px;height:52px;flex-shrink:0;display:flex;align-items:center;justify-content:center;cursor:pointer;padding:0 8px;font-size:10px;font-weight:800;letter-spacing:0.1em;color:white;">${(()=>{ const _src=S.logos?.fia_pen||S.logos?.fia||imgSrc('logo_fia_pen')||imgSrc('logo_fia'); return _src?`<img src="${_src}" style="width:44px;height:44px;object-fit:contain;">`:'FIA'; })()}</div>
      </div>
      ${rowsHtml}
    </div>`;
  }).join('');

  } catch (_e) { delete _renderState['renderPenaltiesPublic']; _renderError('penalties-public-list', 'renderPenaltiesPublic', _e); }
}

