function renderPenalties() {
  try {
  const dSel=document.getElementById('pen-driver-select');
  const rSel=document.getElementById('pen-race-select');
  if(!dSel||!rSel)return;
  const curD=dSel.value,curR=rSel.value;
  dSel.innerHTML='<option value="">— Piloto —</option>';
  S.drivers.forEach(d=>{const o=document.createElement('option');o.value=d.id;o.textContent=d.name;dSel.appendChild(o);});
  if(curD)dSel.value=curD;
  rSel.innerHTML='<option value="">— GP —</option>';
  S.races.forEach(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.name;rSel.appendChild(o);});
  if(curR)rSel.value=curR;
  const container=document.getElementById('penalties-table-container');
  if(!container)return;
  const pens=S.penalties||[];
  if(!pens.length){container.innerHTML='<div class="pen-empty">No hay sanciones registradas</div>';return;}
  const rows=pens.map(p=>{
    const driver=S.drivers.find(d=>d.id===p.driverId);
    const race=S.races.find(r=>r.id===p.raceId);
    const flagImg=race?.countryCode?`<img class="pen-gp-flag" src="https://flagcdn.com/w40/${race.countryCode.toLowerCase()}.png">`:(race?.flag||'🏁');
    const teamName=driver?(TEAM_NAMES_FULL[driver.team]||driver.team):'';
    return `<tr>
      <td><span class="pen-driver">${driver?.name||'—'}</span><span class="pen-driver-team">${teamName}</span></td>
      <td><div class="pen-gp">${flagImg}<span>${race?.name?.replace('GRAN PREMIO DE ','').replace('GRAN PREMIO DEL ','')||'—'}</span></div></td>
      <td class="pen-type">${p.type||'—'}</td>
      <td class="pen-sanction">${p.sanction||'—'}</td>
      <td class="pen-note">${p.note||''}</td>
      <td><div class="pen-actions">
        <button class="pen-btn" onclick="editPenalty('${p.id}')">✏️</button>
        <button class="pen-btn" onclick="deletePenalty('${p.id}')">🗑</button>
      </div></td>
    </tr>`;
  }).join('');
  container.innerHTML=`<table class="pen-table"><thead><tr><th>Piloto</th><th>Gran Premio</th><th>Infracción</th><th>Sanción</th><th>Nota</th><th></th></tr></thead><tbody>${rows}</tbody></table>`;

  } catch (_e) { _renderError('penalties-table-container', 'renderPenalties', _e); }
}

