function uploadFlag(country, code) {
  if (!country && !code) return;
  const slug = (country||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');
  const cc = (code||'').toLowerCase();
  if (!slug && !cc) return;
  const input = document.createElement('input');
  input.type='file'; input.accept='image/*';
  input.onchange = e => {
    const file=e.target.files[0]; if(!file) return;
    const reader=new FileReader();
    reader.onload = ev => {
      if(!S.logos) S.logos={};
      if (slug) S.logos['flag_'+slug] = ev.target.result;
      if (cc) S.logos['flag_'+cc] = ev.target.result;
      saveState();
      if(typeof renderCalendario==='function') renderCalendario();
      if(typeof showNotif==='function') showNotif('🚩 Bandera de '+(country||cc)+' guardada');
    };
    reader.readAsDataURL(file);
  };
  input.click();
}

function uploadTrophy(driverId, slot) {
  const input=document.createElement('input');
  input.type='file';input.accept='image/*';
  input.onchange=e=>{
    const file=e.target.files[0];if(!file)return;
    const reader=new FileReader();
    reader.onload=ev=>{
      if(!S.driverProfiles[driverId])S.driverProfiles[driverId]={};
      if(!S.driverProfiles[driverId].trophies)S.driverProfiles[driverId].trophies={};
      S.driverProfiles[driverId].trophies[slot]=ev.target.result;
      saveState();openProfile(driverId);showNotif('🏆 Trofeo guardado');
    };
    reader.readAsDataURL(file);
  };
  input.click();
}

function exportProfileJPG(driverId) {
  const target = document.getElementById('view-profile');
  if (!target) return;
  showNotif('📸 Generando imagen...');
  const lastSaved = document.getElementById('last-saved-indicator');
  if (lastSaved) lastSaved.style.display = 'none';
  html2canvas(target, { backgroundColor:'#050508', scale:2, useCORS:true, allowTaint:true, logging:false })
    .then(canvas => {
      const driver = S.drivers.find(d => d.id === driverId);
      const link = document.createElement('a');
      link.download = `LEALA_PILOTO_${driver?.name||'PILOTO'}.jpg`;
      link.href = canvas.toDataURL('image/jpeg', 0.92);
      link.click();
      if (lastSaved) lastSaved.style.display = '';
      showNotif('✅ Imagen descargada');
    }).catch(() => { if (lastSaved) lastSaved.style.display = ''; showNotif('⚠ Error'); });
}

function openTeam(teamKey) {
  // McLaren (bright orange) needs dark text; all others use white
  const darkTextTeams = ['team-mclaren','mclaren'];
  const useDark = darkTextTeams.includes(teamKey);
  const textMain   = useDark ? 'rgba(0,0,0,0.85)'  : 'rgba(255,255,255,0.95)';
  const textSub    = useDark ? 'rgba(0,0,0,0.5)'   : 'rgba(255,255,255,0.55)';
  const textMuted  = useDark ? 'rgba(0,0,0,0.35)'  : 'rgba(255,255,255,0.3)';
  const borderSep  = useDark ? 'rgba(0,0,0,0.25)'  : 'rgba(0,0,0,0.35)';
  const standings = computeTeamStandings();
  const team = standings.find(t=>t.teamKey===teamKey);
  if(!team) return;
  const accent = getTeamAccent(teamKey);
  const sep = _darken(_darken(accent));
  const teamName = TEAM_NAMES_FULL[teamKey]||teamKey;
  const storedLogo = (S.logos&&S.logos[`teamLogo_${teamKey}`])||imgSrc('logo_teamLogo_'+teamKey);

  // Team rank
  const teamRank = standings.findIndex(t=>t.teamKey===teamKey)+1;

  // Car photo slot
  const carSrc = (S.logos&&S.logos[`teamCar_${teamKey}`])||imgSrc('logo_teamCar_'+teamKey);
  const carImg = carSrc
    ? `<img src="${carSrc}" style="width:100%;height:100%;object-fit:cover;object-position:center;display:block;">`
    : `<div style="color:rgba(255,255,255,0.18);font-size:12px;letter-spacing:0.12em;text-transform:uppercase;font-family:'Barlow Condensed',sans-serif;z-index:2;">Foto del coche</div>`;

  // Per-driver cards (row 3)
  const driverCardsHTML = team.drivers.map(d=>{
    const stats = driverStats(d.id);
    const _drvPhoto = S.driverProfiles[d.id]?.photoDataUrl || imgSrc('dp_'+d.id);
    const photo = _drvPhoto
      ? `<img src="${_drvPhoto}" style="width:100%;height:100%;object-fit:cover;object-position:top;">`
      : `<div style="font-size:40px;opacity:0.15;display:flex;align-items:center;justify-content:center;height:100%;">👤</div>`;
    const _tiSrc2=imgSrc('ti_'+d.id);
    const teamImgEl = _tiSrc2
      ? `<img src="${_tiSrc2}" style="max-height:28px;max-width:60px;object-fit:contain;opacity:0.7;">`
      : '';
    return `<div class="td2-card" style="background:radial-gradient(ellipse at top left,${accent},${_darken(accent)});border-right:1px solid ${sep};border-radius:0px;" data-accent="${accent}">
      <div class="td2-card-left">
        <div class="td2-driver-name" style="color:${textMain}">${d.name}</div>
        <div class="td2-driver-number" style="color:${useDark?'rgba(0,0,0,0.15)':'rgba(255,255,255,0.12)'}">#${d.id}</div>
        <div class="td2-driver-stats">
          <div class="td2-stat"><span class="td2-stat-val" style="color:${textMain}">${stats.wins}</span><span class="td2-stat-lbl" style="color:${textSub}">Vic</span></div>
          <div class="td2-stat"><span class="td2-stat-val" style="color:${textMain}">${stats.poles}</span><span class="td2-stat-lbl" style="color:${textSub}">PP</span></div>
          <div class="td2-stat"><span class="td2-stat-val" style="color:${textMain}">${stats.fastestLaps}</span><span class="td2-stat-lbl" style="color:${textSub}">VR</span></div>
          <div class="td2-stat"><span class="td2-stat-val" style="color:${textMain}">${stats.podiums}</span><span class="td2-stat-lbl" style="color:${textSub}">Pod</span></div>
        </div>
        <div style="margin-top:8px;display:flex;align-items:center;gap:12px;">${teamImgEl}<span style="font-family:'Russo One',sans-serif;font-size:16px;color:${textMain};">${stats.totalPts} pts</span></div>
        <div style="margin-top:auto;padding-top:8px;">
          <button class="td2-profile-btn" onclick="openProfile(${d.id})" style="border-color:${textSub};color:${textMain};">Ver perfil →</button>
        </div>
      </div>
      <div class="td2-card-photo" onclick="openProfile(${d.id})" style="background:${sep};">${photo}</div>
    </div>`;
  }).join('');

  // Row 4: joint stats + team summary
  let bothInPts = 0;
  let bestResult = 99, bestRaceName = '—';
  // Mejor resultado CONJUNTO del equipo: carrera donde sumó más puntos (sin VR)
  let bestCombinedPts = -1, bestCombinedPositions = null;
  S.races.forEach(race=>{
    const allIn = team.drivers.every(d=>{ const p=race.results[d.id]; return p&&(S.pointsSystem[p]||0)>0; });
    if(allIn) bothInPts++;
    // Acumulación conjunta sin VR
    const drvInfo = team.drivers.map(d => {
      const pos = race.results?.[d.id];
      const pts = (pos && pos > 0) ? (S.pointsSystem[pos]||0) : 0;
      return {pos, pts};
    });
    const totalPts = drvInfo.reduce((a,b) => a+b.pts, 0);
    if (totalPts > bestCombinedPts) {
      bestCombinedPts = totalPts;
      bestCombinedPositions = drvInfo.map(x => x.pos);
      bestRaceName = race.name.replace('GRAN PREMIO DE ','').replace('GRAN PREMIO DEL ','');
    }
    // Mejor posición individual (se conserva por si se usa en otro sitio)
    team.drivers.forEach(d=>{
      const p = race.results?.[d.id]||99;
      if(p>0 && p<bestResult){ bestResult=p; }
    });
  });
  const bestCombinedDisplay = (bestCombinedPts > 0 && bestCombinedPositions)
    ? bestCombinedPositions.map(p => p>0?'P'+p:'—').join('+')
    : '—';
  const bestCombinedSub = (bestCombinedPts > 0) ? `${bestCombinedPts}pts · ${bestRaceName}` : '—';

  const teamLogoEl = storedLogo
    ? `<img src="${storedLogo}" style="max-height:32px;max-width:80px;object-fit:contain;">`
    : `<span style="font-family:'Russo One',sans-serif;font-size:18px;color:${accent};">${TEAM_NAMES[teamKey]||'?'}</span>`;

  document.getElementById('team-detail-content').innerHTML = `
  <div class="td2-wrap">

    <!-- ROW 1: Car photo -->
    <div class="td2-row1" style="background:${accent};">
      <div class="td2-car-slot" onclick="uploadTeamCar('${teamKey}')" title="Subir foto del coche">
        ${carImg}
        <div class="td2-car-hint"></div>
      </div>
    </div>

    <!-- SEPARATOR -->

    <!-- ROW 2: Team name -->
    <div class="td2-row2" style="background:linear-gradient(180deg,${accent},${accent}dd);">
      <div class="td2-team-name-big" style="color:${textMain};">${teamName}</div>
      <div class="td2-team-drivers-row" style="color:${textSub};">${team.drivers.map(d=>`<span>${d.name}</span>`).join('<span class="td2-sep-dot" style="color:${textMuted}">·</span>')}</div>
    </div>

    <!-- SEPARATOR -->

    <!-- ROW 4 FIRST: Team stats (swapped) -->
    <div class="td2-row4" style="border-top:1px solid ${sep};">
      <div class="td2-stat-block" style="background:linear-gradient(135deg,${accent}ee,${accent}cc);border-right:1px solid ${sep};border-radius:0;">
        <div class="td2-stat-block-title" style="color:${textSub};">Clasificación</div>
        <div class="td2-stat-block-val" style="color:${textMain};">P${teamRank}</div>
        <div class="td2-stat-block-sub" style="color:${textSub};">${team.pts} pts</div>
      </div>
      <div class="td2-stat-block" style="background:linear-gradient(135deg,${accent}ee,${accent}cc);border-right:1px solid ${sep};">
        <div class="td2-stat-block-title" style="color:${textSub};">Victorias</div>
        <div class="td2-stat-block-val" style="color:${textMain};">${team.wins}</div>
        <div class="td2-stat-block-sub" style="color:${textSub};">${team.podiums} podios</div>
      </div>
      <div class="td2-stat-block" style="background:linear-gradient(135deg,${accent}ee,${accent}cc);border-right:1px solid ${sep};">
        <div class="td2-stat-block-title" style="color:${textSub};">Poles</div>
        <div class="td2-stat-block-val" style="color:${textMain};">${team.poles}</div>
        <div class="td2-stat-block-sub" style="color:${textSub};">${team.fastestLaps} VR</div>
      </div>
      <div class="td2-stat-block" style="background:linear-gradient(135deg,${accent}ee,${accent}cc);border-right:none;border-radius:0;">
        <div class="td2-stat-block-title" style="color:${textSub};">Mejor resultado</div>
        <div class="td2-stat-block-val" style="color:${textMain};">${bestCombinedDisplay}</div>
        <div class="td2-stat-block-sub" style="color:${textSub};">${bestCombinedSub}</div>
      </div>
    </div>

    <!-- SEPARATOR -->

    <!-- ROW 3 SECOND: Driver cards (swapped) -->
    <div class="td2-row3" style="background:${sep};">${driverCardsHTML}</div>

    <!-- ROW 5: Palmarés acumulado del equipo -->
    ${(() => {
      const driverIds = team.drivers.map(d => d.id);
      const wins = (S.races||[]).filter(r => {
        const winner = Object.entries(r.results||{}).find(([id,pos]) => pos===1);
        return winner && driverIds.includes(parseInt(winner[0]));
      }).sort((a,b) => (a.round||0) - (b.round||0));
      return `<div class="td2-palmares-band">
        <div class="palm-title">Palmarés del equipo</div>
        ${wins.length === 0
          ? `<div class="td2-palm-empty">Sin trofeos todavía</div>`
          : wins.map(race => {
              const src = imgSrc(`trophy_${race.round}`);
              const gpShort = (race.name||'').replace(/^gran\\s+premio\\s+(de\\s+|del\\s+)?/i,'').toUpperCase();
              const cc = race.cc || race.flag || '';
              const flagImg = cc ? `<img class="palm-flag" src="assets/flags/${cc.toLowerCase()}_flag.webp" alt="" onerror="this.style.display='none'">` : '';
              return `<div class="td2-palm-wrap"><div class="td2-palm-slot" title="GP ${gpShort} — R${race.round}">${src?`<img src="${src}" alt="">`:'<span style=\"font-size:24px;\">🏆</span>'}</div>${flagImg}</div>`;
            }).join('')}
      </div>`;
    })()}

  </div>`;
    document.getElementById('teams-list-view').style.display='none';
  document.getElementById('teams-detail-view').style.display='block';
}

