//


// _renderCircuitDataBlock — pinta el bloque de Datos Técnicos del Circuito
// dentro de la ficha. Los 6 campos sensibles llevan la clase admin-only.
// El bloque NO usa imágenes/base64; tira de CIRCUIT_DATA + de la propia race
// (para meteo/SC reales del GP disputado).
function _renderCircuitDataBlock(race, isNextGp) {
  const data = getCircuitData(race);
  if (!data) return '';   // Circuito no presente en la base de datos técnica
  const row = (label, value, adminOnly) => `
    <div class="cd-circuit-data-row${adminOnly ? ' admin-only' : ''}">
      <span class="label">${label}</span>
      <span class="value${(value === '—' || value == null) ? ' muted' : ''}">${value == null ? '—' : value}</span>
    </div>`;
  const runoffStr = (data.runoff && data.runoff.length === 4)
    ? `${data.runoff[0]}/${data.runoff[1]}/${data.runoff[2]}/${data.runoff[3]} %`
    : '—';

  // Tipo de qualy, meteo y SC: del calendario (próximo GP) o de la race.
  let qualyTypeVal, weatherVal, scVal, nextGpObj = null;
  if (isNextGp) {
    nextGpObj = (S.calendario || []).find(g => Number(g.round) === Number(race.round));
    qualyTypeVal = (nextGpObj && nextGpObj.qualyType) ? nextGpObj.qualyType : '—';
    const rainEff = (nextGpObj && nextGpObj.rainPctManual != null)
      ? nextGpObj.rainPctManual : data.rainPct;
    weatherVal = (rainEff != null)
      ? (rainEff >= 70 ? `Lluvia (${rainEff}%)`
        : rainEff >= 45 ? `Mixto (${rainEff}%)` : `Seco (${rainEff}%)`)
      : '—';
    scVal = (data.historicalSC != null) ? `${data.historicalSC} (media últimas 5 ediciones)` : '—';
  } else {
    qualyTypeVal = race.qualyType || '—';
    weatherVal = race.weather || '—';
    scVal = (race.safetyCarCount != null) ? String(race.safetyCarCount) : '—';
  }

  // Sección de edición del próximo GP (sólo admin): tipo de qualy + meteo.
  let editSection = '';
  if (isNextGp) {
    const curQT = (nextGpObj && nextGpObj.qualyType) || '';
    const curRP = (nextGpObj && nextGpObj.rainPctManual != null)
      ? nextGpObj.rainPctManual
      : (data.rainPct != null ? data.rainPct : '');
    const qtOpts = QUALY_TYPES.map(q =>
      `<option value="${q}"${curQT === q ? ' selected' : ''}>${q}</option>`).join('');
    editSection = `
      <div class="cd-nextgp-edit admin-only">
        <div class="cd-edit-title">Editar datos del próximo GP</div>
        <div class="cd-edit-grid">
          <div class="cd-edit-field">
            <label>Tipo de Qualy</label>
            <select id="cd-edit-qualytype"><option value="">—</option>${qtOpts}</select>
          </div>
          <div class="cd-edit-field">
            <label>Probabilidad de lluvia (%)</label>
            <input type="number" id="cd-edit-rainpct" min="0" max="100" value="${curRP}">
          </div>
        </div>
        <button class="cd-edit-save" onclick="saveNextGpData(${race.round})">Guardar datos del próximo GP</button>
      </div>`;
  }

  return `
    <div class="cd-circuit-data">
      <div class="cd-circuit-data-title">Datos técnicos del circuito</div>
      <div class="cd-circuit-data-grid">
        ${row('Longitud', `${data.lengthM} m`, false)}
        ${row('Vuelta rápida (referencia)', data.fastestLap, false)}
        ${row('Nº curvas totales', data.numCorners, false)}
        ${row('Velocidad punta', `${data.topSpeedKmh} km/h`, false)}
        ${row('Tipo de circuito', (data.circuitType || '').replace(/^./, c => c.toUpperCase()), false)}
        ${row('Tipo de Qualy', qualyTypeVal, false)}
        ${row('Escapatorias (M/G/H/A)', runoffStr, true)}
        ${row('Distancia salida → 1ª curva', `${data.firstCornerDistM} m`, false)}
        ${row('Curvas de alta velocidad', data.highSpeedCorners, false)}
        ${row('Curvas de baja velocidad', data.lowSpeedCorners, false)}
        ${row('Velocidad media', `${data.avgSpeedKmh} km/h`, false)}
        ${row(isNextGp ? 'Meteorología prevista' : 'Meteorología', weatherVal, false)}
        ${row(isNextGp ? 'Histórico SC' : 'SCs durante la carrera', scVal, false)}
      </div>
      ${editSection}
    </div>`;
}

function openCircuit(raceId) {
  // Admite dos modos:
  //   - raceId numérico  => GP disputado (S.races)
  //   - "next-<round>"   => próximo GP (S.calendario), Qualy/Carrera vacíos.
  let race, raceIndex, isNextGp = false;
  if (typeof raceId === 'string' && raceId.indexOf('next-') === 0) {
    const rnd = parseInt(raceId.slice(5), 10);
    const gp = (S.calendario || []).find(g => Number(g.round || 0) === rnd);
    if (!gp) return;
    race = {
      id: raceId,
      name: gp.name,
      round: gp.round,
      flag: gp.flag,
      countryCode: gp.flag,
      country: gp.country,
      results: {}, qualResults: {}, qualTimes: {},
      pole: null, fastestLap: null,
    };
    raceIndex = -1;
    isNextGp = true;
  } else {
    race = S.races.find(r => r.id === raceId);
    if (!race) return;
    raceIndex = S.races.findIndex(r => r.id === raceId);
  }
  const racePairs=Object.entries(race.results||{})
  .map(([id,pos])=>({driver:S.drivers.find(d=>d.id===parseInt(id)),pos}))
  .filter(x=>x.driver)
  .sort((a,b)=>{
    if(a.pos===0&&b.pos===0)return 0;
    if(a.pos===0)return 1;
    if(b.pos===0)return -1;
    return a.pos-b.pos;
  });
  const qualPairs=Object.entries(race.qualResults||{})
  .map(([id,pos])=>({driver:S.drivers.find(d=>d.id===parseInt(id)),pos}))
  .filter(x=>x.driver).sort((a,b)=>a.pos-b.pos);
  const posCol=p=>p===1?'p1c':p===2?'p2c':p===3?'p3c':'';
  const raceRows=racePairs.map(({driver,pos})=>{
    const nameCls=pos===1?'p1c':pos===2?'p2c':pos===3?'p3c':'';
    return `
  <div class="cd-res-row">
    <span class="cd-res-pos ${pos>0?posCol(pos):''}" style="${pos===0?'color:#555;font-size:12px;':''}">` +
    `${pos>0?pos:'DNF'}</span>
    <span class="cd-res-name ${nameCls}">${driver.name}</span>
    <span class="cd-res-pts">${pos>0?'+'+((S.pointsSystem[pos]||0)+(race.fastestLap===driver.id?1:0))+'p':''}</span>
  </div>`;
  }).join('');
  const qualRows=qualPairs.map(({driver,pos})=>{
    const qt = race.qualTimes?.[driver.id] ?? race.qualTimes?.[String(driver.id)];
    const qtStr = qt !== undefined ? formatQualTime(qt) : '';
    return `
  <div class="cd-res-row">
    <span class="cd-res-pos ${posCol(pos)}">${pos}</span>
    <span class="cd-res-name">${driver.name}</span>
    ${qtStr?`<span class="cd-res-pts" style="color:#aaa;font-size:11px;">${qtStr}</span>`:''}
  </div>`;
  }).join('');
  const flDriver=race.fastestLap?S.drivers.find(d=>d.id===race.fastestLap):null;
  let winnerDriver=null;
  if (race.results) {
    const _winId = Object.keys(race.results).find(k => race.results[k] === 1);
    if (_winId) winnerDriver = S.drivers.find(d => d.id == _winId);
  }
  const poleDriver=race.pole?S.drivers.find(d=>d.id===race.pole):null;
  const _layoutSrcX=imgSrc('layout_'+race.id);
  const layoutImg=_layoutSrcX
  ?`<img src="${_layoutSrcX}" alt="Trazado">`
  :`<div class="layout-slot-hint"><span>🗺</span>Clic para añadir<br>trazado del circuito</div>`;
  const _countrySlug=(race.country||'').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');
  const _emojiFb=(race.flag||'🏁').replace(/'/g,"\\'");
  const _circCC=(race.flag||'').toLowerCase();
  const _circEmojiU=_circCC.length===2?String.fromCodePoint(..._circCC.split('').map(c=>0x1F1E6+c.charCodeAt(0)-97)):'🏁';
  const _circUserImg=(S.logos&&(S.logos['flag_'+_countrySlug]||S.logos['flag_'+_circCC]))||null;
  const flagImg = _countrySlug
    ? `<span style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:40px;line-height:1;z-index:-1;">${_circEmojiU}</span><img src="${_circUserImg||('assets/flags/'+_circCC+'_flag.webp')}" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;z-index:1;" onerror="if(this.src.indexOf('data:')===0){return;}if(!this.dataset.fb){this.dataset.fb='1';this.src='assets/flags/${_circCC}-sq_flag.webp';}else{this.remove();}">`
    : `<span style="font-size:40px">${_circEmojiU}</span>`;
  const circuitPhotoKey=`circuitPhoto_${raceId}`;
  const _circPhotoSrc=(S.logos&&S.logos[circuitPhotoKey])||imgSrc(circuitPhotoKey);
  const circuitPhoto=_circPhotoSrc
  ?`<img src="${_circPhotoSrc}" alt="Foto circuito">`
  :`<div class="cd-hero-photo-hint">Foto circuito</div>`;
  const histText=getCircuitHistory(race);
  const before=isNextGp?[]:standingsBeforeRace(raceIndex);
  const after=isNextGp?[]:standingsAfterRace(raceIndex);
  const stdPosClass=p=>p===1?'p1':p===2?'p2':p===3?'p3':'';
  const beforeMap={};
  before.forEach((d,i)=>{ beforeMap[d.id]=i+1; });
  const stdRows=(arr,showArrows)=>arr.slice(0,8).map((d,i)=>{
    const prevPos=showArrows?beforeMap[d.id]:null;
    const diff=prevPos?(prevPos-(i+1)):0;
    const arrows=showArrows&&diff!==0?(diff>0?'+'+diff:String(diff)):'';
    const arrowCls=diff>0?'style="color:#4CAF50"':diff<0?'style="color:var(--red)"':'';
    return `
  <div class="cd-std-row">
    <span class="cd-std-pos ${stdPosClass(i+1)}">${i+1}</span>
    <span class="cd-std-name">${d.name}</span>
    ${arrows?`<span class="cd-std-arrow" ${arrowCls}>${arrows}</span>`:''}
    <span class="cd-std-pts">${d.points}p</span>
  </div>`;
  }).join('');
  const pressText=S.circuitPress?.[raceId]||'';
  const totalRounds=isNextGp?(S.calendario||[]).length:S.races.length;
  document.getElementById('circuit-detail-content').innerHTML=`
  ${isNextGp ? '<div class="cd-next-gp-banner">PRÓXIMO GP — AÚN NO DISPUTADO</div>' : ''}

  <!-- BANDA 1: bandera + foto + nombre -->
  <div class="cd-hero">
    <div class="cd-hero-flag" onclick="uploadFlag('${race.country||''}','${race.flag||''}')" style="cursor:pointer;" title="Clic para subir bandera">${flagImg}</div>
    <div class="cd-hero-photo" onclick="uploadCircuitPhoto('${raceId}')" title="Clic para añadir foto">
      ${circuitPhoto}
    </div>
    <div class="cd-hero-info">
      <div class="cd-round">Ronda ${race.round} / ${totalRounds}</div>
      <div class="cd-name">${race.name}</div>
      <div class="cd-country-text">${race.country||''}</div>
    </div>
  </div>

  <!-- EXTRAS: POLE, VR, VICTORIA -->
  <div class="cd-extras">
    ${poleDriver?`<div class="cd-extra-item"><span class="cd-extra-badge pole">POLE</span><span class="cd-extra-name">${poleDriver.name}</span></div>`:''}
    ${flDriver?`<div class="cd-extra-item"><span class="cd-extra-badge fl">VUELTA RÁPIDA</span><span class="cd-extra-name">${flDriver.name}</span></div>`:''}
    ${winnerDriver?`<div class="cd-extra-item"><span class="cd-extra-badge winner">VICTORIA</span><span class="cd-extra-name">${winnerDriver.name}</span></div>`:''}
  </div>

  <!-- BANDA 2: trazado (2fr) + datos históricos (1fr) -->
  <div class="cd-mid-band">
    <div class="cd-mid-layout circuit-layout-slot" onclick="uploadCircuitLayout('${raceId}')" id="layout-slot-${raceId}">
      ${layoutImg}
    </div>
    <div class="cd-mid-history cd-history-block">
      <div class="cd-history-title">Datos históricos F1</div>
      <div class="cd-history-text" id="cd-hist-text-${raceId}" style="white-space:pre-line">${histText||'Sin datos históricos.'}</div>
      <textarea class="cd-history-textarea" id="cd-hist-ta-${raceId}"></textarea>
      <button class="cd-history-edit-btn" id="cd-hist-edit-${raceId}" onclick="toggleHistoryEdit('${raceId}')">✏️ Editar</button>
      <button class="cd-history-save-btn" id="cd-hist-save-${raceId}" onclick="saveHistoryEdit('${raceId}')">💾 Guardar</button>
    </div>
  </div>

  <!-- BANDA 3: datos técnicos -->
  ${_renderCircuitDataBlock(race, isNextGp)}

  <!-- BANDA 4: resultados (qualy, carrera, prensa, después) -->
  <div class="cd-bottom">
    <div class="cd-col qualy">
      <div class="cd-col-header qualy-header">Clasificación (Qualy)</div>
      <div class="cd-results-section">${qualRows||'<p style="color:#333;font-size:12px;padding:12px;">Sin datos</p>'}</div>
    </div>
    <div class="cd-col race-col">
      <div class="cd-col-header checkered-header">Carrera</div>
      <div class="cd-results-section">${raceRows||'<p style="color:#333;font-size:12px;padding:12px;">Sin datos</p>'}</div>
    </div>
    <div class="cd-col">
      <div class="cd-col-header">📰 Nota de prensa</div>
      <div class="cd-press-body">
        <div class="cd-press-text${pressText?'':' placeholder'}" id="cd-press-text-${raceId}" data-raw="${pressText}">${pressText||'Pulsa ✏️ para añadir una nota de prensa.'}</div>
        <textarea class="cd-press-textarea" id="cd-press-ta-${raceId}"></textarea>
        <button class="cd-press-edit-btn" id="cd-press-edit-${raceId}" onclick="togglePressEdit('${raceId}')">✏️ Nota de prensa</button>
        <button class="cd-press-save-btn" id="cd-press-save-${raceId}" onclick="savePressEdit('${raceId}')">💾 Guardar</button>
      </div>
    </div>
    <div class="cd-col after">
      <div class="cd-col-header">Clasificación después del GP</div>
      <div class="cd-standings-list">${isNextGp?'<p style="color:#333;font-size:12px;padding:12px;">Aún no disputado</p>':stdRows(after,true)}</div>
    </div>
  </div>
  `;
  document.getElementById('circuits-list-view').style.display='none';
  document.getElementById('circuits-detail-view').style.display='block';
  // Add export button
  if (!isNextGp) {
    const circuitExportDiv = document.createElement('div');
    circuitExportDiv.style.cssText = 'text-align:center;padding:16px 0;';
    circuitExportDiv.innerHTML = ``; // Botón de exportar eliminado
    document.getElementById('circuit-detail-content').appendChild(circuitExportDiv);
  }
}

function calNavigateToCircuit(cc, gpName, round) {
  const race = S.races.find(r =>
    (r.countryCode||r.flag||'').toLowerCase().slice(0,2) === cc ||
    (r.name||'').toLowerCase() === (gpName||'').toLowerCase()
  );
  const circBtn = document.querySelector('.nav-btn[title="Grandes Premios"]');
  showView('circuits', circBtn);
  if (race) openCircuit(race.id);
  else if (round) openCircuit('next-' + round);
}

