function uploadCircuitPhoto(raceId) {
  const input=document.createElement('input');
  input.type='file'; input.accept='image/*';
  input.onchange=e=>{
  const file=e.target.files[0]; if(!file)return;
  const reader=new FileReader();
  reader.onload=ev=>{
    if(!S.logos)S.logos={};
    S.logos[`circuitPhoto_${raceId}`]=ev.target.result;
    saveState(); openCircuit(raceId); showNotif('✅ Foto del circuito guardada');
  };
  reader.readAsDataURL(file);
  };
  input.click();
}

function uploadCircuitLayout(raceId) {
  const input=document.createElement('input');
  input.type='file'; input.accept='image/*';
  input.onchange=e=>{
  const file=e.target.files[0]; if(!file)return;
  const reader=new FileReader();
  reader.onload=ev=>{
    const race=S.races.find(r=>r.id===raceId);
    if(race){ race.layoutDataUrl=ev.target.result; saveState(); openCircuit(raceId); showNotif('✅ Trazado guardado'); }
  };
  reader.readAsDataURL(file);
  };
  input.click();
}

function saveCircuitHistory(raceId, text) {
  if(!S.circuitHistory) S.circuitHistory = {};
  S.circuitHistory[raceId] = text;
  saveState();
}

function toggleHistoryEdit(raceId) {
  const textEl = document.getElementById(`cd-hist-text-${raceId}`);
  const taEl   = document.getElementById(`cd-hist-ta-${raceId}`);
  const saveBtn= document.getElementById(`cd-hist-save-${raceId}`);
  const editBtn= document.getElementById(`cd-hist-edit-${raceId}`);
  const isEditing = taEl.style.display !== 'none';
  if(isEditing) {
  textEl.style.display=''; taEl.style.display='none';
  saveBtn.style.display='none'; editBtn.textContent='✏️ Editar';
  } else {
  taEl.value = textEl.textContent;
  textEl.style.display='none'; taEl.style.display='block';
  saveBtn.style.display='inline-block'; editBtn.textContent='✕ Cancelar';
  }
}

function saveHistoryEdit(raceId) {
  const taEl  = document.getElementById(`cd-hist-ta-${raceId}`);
  const textEl= document.getElementById(`cd-hist-text-${raceId}`);
  const saveBtn=document.getElementById(`cd-hist-save-${raceId}`);
  const editBtn=document.getElementById(`cd-hist-edit-${raceId}`);
  textEl.textContent = taEl.value;
  saveCircuitHistory(raceId, taEl.value);
  textEl.style.display=''; taEl.style.display='none';
  saveBtn.style.display='none'; editBtn.textContent='✏️ Editar';
  showNotif('✅ Datos históricos guardados');
}

function saveCircuitPress(raceId, text) {
  if(!S.circuitPress) S.circuitPress = {};
  S.circuitPress[raceId] = text;
  saveState();
}

function togglePressEdit(raceId) {
  const textEl = document.getElementById(`cd-press-text-${raceId}`);
  const taEl   = document.getElementById(`cd-press-ta-${raceId}`);
  const saveBtn= document.getElementById(`cd-press-save-${raceId}`);
  const editBtn= document.getElementById(`cd-press-edit-${raceId}`);
  const isEditing = taEl.style.display !== 'none';
  if(isEditing) {
  textEl.style.display=''; taEl.style.display='none';
  saveBtn.style.display='none'; editBtn.textContent='✏️ Nota de prensa';
  } else {
  taEl.value = textEl.dataset.raw||textEl.textContent;
  textEl.style.display='none'; taEl.style.display='block';
  saveBtn.style.display='inline-block'; editBtn.textContent='✕ Cancelar';
  }
}

function savePressEdit(raceId) {
  const taEl  = document.getElementById(`cd-press-ta-${raceId}`);
  const textEl= document.getElementById(`cd-press-text-${raceId}`);
  const saveBtn=document.getElementById(`cd-press-save-${raceId}`);
  const editBtn=document.getElementById(`cd-press-edit-${raceId}`);
  const val = taEl.value.trim();
  textEl.dataset.raw = val;
  textEl.textContent = val || '';
  textEl.className = 'cd-press-text' + (val ? '' : ' placeholder');
  if(!val) textEl.textContent = 'Sin nota de prensa todavía. Pulsa ✏️ para añadir.';
  saveCircuitPress(raceId, val);
  textEl.style.display=''; taEl.style.display='none';
  saveBtn.style.display='none'; editBtn.textContent='✏️ Nota de prensa';
  showNotif('✅ Nota de prensa guardada');
}

function exportCircuitJPG(raceId) {
  const target = document.getElementById('circuit-detail-content');
  if (!target) return;
  showNotif('📸 Generando imagen...');
  const lastSaved = document.getElementById('last-saved-indicator');
  if (lastSaved) lastSaved.style.display = 'none';
  html2canvas(target, { backgroundColor:'#050508', scale:2, useCORS:true, allowTaint:true, logging:false })
    .then(canvas => {
      const race = S.races.find(r => r.id === raceId);
      const link = document.createElement('a');
      link.download = `LEALA_CIRCUITO_${race?.name?.replace(/\s+/g,'_')||'GP'}.jpg`;
      link.href = canvas.toDataURL('image/jpeg', 0.92);
      link.click();
      if (lastSaved) lastSaved.style.display = '';
      showNotif('✅ Imagen descargada');
    }).catch(() => { if (lastSaved) lastSaved.style.display = ''; showNotif('⚠ Error'); });
}

function exportDuelJPG() {
  const target = document.getElementById('duel-result');
  if (!target || !target.children.length) { showNotif('⚠ No hay duelo para exportar'); return; }
  showNotif('📸 Generando imagen...');
  const exportBtn = document.getElementById('duel-export-btn-container');
  if (exportBtn) exportBtn.style.display = 'none';
  const lastSaved = document.getElementById('last-saved-indicator');
  if (lastSaved) lastSaved.style.display = 'none';
  html2canvas(target, {
    backgroundColor: '#050508',
    scale: 2,
    useCORS: true,
    allowTaint: true,
    logging: false,
  }).then(canvas => {
    const idA = parseInt(document.getElementById('duel-select-a').value);
    const idB = parseInt(document.getElementById('duel-select-b').value);
    const dA = S.drivers.find(d => d.id === idA);
    const dB = S.drivers.find(d => d.id === idB);
    const name = (dA && dB) ? `DUELO_${dA.name}_vs_${dB.name}` : 'DUELO';
    const link = document.createElement('a');
    link.download = `${name}.jpg`;
    link.href = canvas.toDataURL('image/jpeg', 0.95);
    link.click();
    if (exportBtn) exportBtn.style.display = '';
    if (lastSaved) lastSaved.style.display = '';
    showNotif('✅ Imagen descargada');
  }).catch(e => {
    if (exportBtn) exportBtn.style.display = '';
    if (lastSaved) lastSaved.style.display = '';
    showNotif('⚠ Error al generar imagen');
  });
}

function submitPenalty(){
  const driverId=parseInt(document.getElementById('pen-driver-select').value);
  const raceId=parseInt(document.getElementById('pen-race-select').value);
  const type=document.getElementById('pen-type').value.trim();
  const sanction=document.getElementById('pen-sanction').value.trim();
  const note=document.getElementById('pen-note').value.trim();
  const editId=document.getElementById('pen-edit-id').value;
  if(!driverId){showNotif('⚠ Selecciona un piloto');return;}
  if(!type){showNotif('⚠ Introduce la infracción');return;}
  if(!sanction){showNotif('⚠ Introduce la sanción');return;}
  if(!S.penalties)S.penalties=[];
  if(editId){
    const idx=S.penalties.findIndex(p=>p.id===editId);
    if(idx>-1)S.penalties[idx]={...S.penalties[idx],driverId,raceId,type,sanction,note};
    showNotif('✅ Sanción actualizada');
  } else {
    S.penalties.push({id:Date.now().toString(),driverId,raceId,type,sanction,note});
    showNotif('✅ Sanción añadida');
  }
  saveState();cancelPenalty();renderPenalties();
}

function editPenalty(id){
  const p=(S.penalties||[]).find(p=>p.id===id);
  if(!p)return;
  document.getElementById('pen-driver-select').value=p.driverId;
  document.getElementById('pen-race-select').value=p.raceId||'';
  document.getElementById('pen-type').value=p.type;
  document.getElementById('pen-sanction').value=p.sanction;
  document.getElementById('pen-note').value=p.note||'';
  document.getElementById('pen-edit-id').value=p.id;
  document.getElementById('pen-cancel-btn').style.display='';
  window.scrollTo({top:0,behavior:'smooth'});
}

function deletePenalty(id){
  if(!confirm('¿Eliminar esta sanción?'))return;
  S.penalties=(S.penalties||[]).filter(p=>p.id!==id);
  saveState();renderPenalties();showNotif('🗑 Sanción eliminada');
}

function cancelPenalty(){
  ['pen-driver-select','pen-race-select','pen-type','pen-sanction','pen-note','pen-edit-id']
    .forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  const btn=document.getElementById('pen-cancel-btn');
  if(btn)btn.style.display='none';
}

function uploadPenFiaLogo() {
  const inp = document.createElement('input');
  inp.type = 'file'; inp.accept = 'image/*';
  inp.onchange = e => {
    const file = e.target.files[0]; if(!file) return;
    const r = new FileReader();
    r.onload = ev => {
      if(!S.logos) S.logos = {};
      S.logos.fia_pen = ev.target.result;   // independent key — does NOT touch S.logos.fia
      saveState();
      document.querySelectorAll('.pen-fia-logo-slot').forEach(el => {
        el.innerHTML = `<img src="${ev.target.result}" style="width:44px;height:44px;object-fit:contain;">`;
      });
    };
    r.readAsDataURL(file);
  };
  inp.click();
}

function openAddNoticia(editIdx) {
  const modal = document.getElementById('add-noticia-modal');
  modal.style.display = 'flex';
  modal.dataset.editIdx = editIdx !== undefined ? editIdx : '';
  if(editIdx !== undefined) {
    const n = (S.noticias||[])[editIdx];
    if(n) {
      document.getElementById('an-title').value = n.title||'';
      document.getElementById('an-tag').value = n.tag||'';
      document.getElementById('an-body').value = n.body||'';
      document.getElementById('an-photo-data').value = n.photo||'';
      if(n.photo) {
        document.getElementById('an-photo-preview').src = n.photo;
        document.getElementById('an-photo-preview').style.display = 'block';
        document.getElementById('an-photo-name').textContent = 'Foto cargada';
      }
    }
  } else {
    document.getElementById('an-title').value='';
    document.getElementById('an-tag').value='';
    document.getElementById('an-body').value='';
    document.getElementById('an-photo-data').value='';
    document.getElementById('an-photo-preview').style.display='none';
    document.getElementById('an-photo-name').textContent='Sin foto';
  }
}

