  document.getElementById('vid-inp-url').value = v?.originalUrl || v?.src || '';
  document.getElementById('vid-inp-round').value = v?.round || '';
  document.getElementById('vid-file-name').textContent = '';
  // Populate GP select from S.races + S.calendario
  const gpSel = document.getElementById('vid-inp-gp');
  const gpList = (S.calendario&&S.calendario.length) ? S.calendario : S.races;
  gpSel.innerHTML = '<option value="">— Sin GP —</option>' +
    gpList.map(g=>{ const n=g.name||''; const r=g.round||''; return `<option value="${n}" data-round="${r}" ${v?.gp===n?'selected':''}>${n}</option>`; }).join('');
