function saveVideo() {
  const title = document.getElementById('vid-inp-title').value.trim();
  const tag   = document.getElementById('vid-inp-tag').value.trim();
  const gp    = document.getElementById('vid-inp-gp').value.trim();
  const round = document.getElementById('vid-inp-round').value.trim();
  let vidObj = { title, tag, gp: gp||null, round: round?Number(round):null };
  if(_vidTab === 'url') {
    const url = document.getElementById('vid-inp-url').value.trim();
    if(!url) { showNotif('⚠️ Introduce una URL'); return; }
    const parsed = parseVideoUrl(url);
    if(!parsed) { showNotif('⚠️ URL no reconocida'); return; }
    Object.assign(vidObj, parsed, { originalUrl: url });
  } else {
    if(!_vidFileData) { showNotif('⚠️ Selecciona un archivo'); return; }
    vidObj = { ...vidObj, type:'local', src:_vidFileData };
  }
  if(!S.videos) S.videos = [];
  if(_vidEditIdx >= 0) S.videos[_vidEditIdx] = vidObj;
  else S.videos.push(vidObj);
  saveState();
  closeVideoModal();
  renderVideos();
  showNotif('✅ Vídeo guardado');
}

function deleteVideo(idx) {
  if(!confirm('¿Eliminar este vídeo?')) return;
  S.videos.splice(idx, 1);
  saveState();
  renderVideos();
}

function openFullVideo(idx) {
  const v = (S.videos||[])[idx]; if(!v) return;
  if(v.type === 'youtube') {
    // Open directly on YouTube — avoids embed restrictions (Error 153)
    const url = v.originalUrl || `https://www.youtube.com/watch?v=${v.ytId}`;
    window.open(url, '_blank', 'noopener');
    return;
  }
  if(v.type === 'vimeo') {
    const url = v.originalUrl || `https://vimeo.com/${v.vimeoId}`;
    window.open(url, '_blank', 'noopener');
    return;
  }
  // Local / direct video: use the inline player
  const embed = getVidEmbed(v);
  const inner = document.getElementById('vid-full-inner');
  document.getElementById('vid-full-title').textContent = v.title||'';
  inner.innerHTML = `<video src="${embed}" controls autoplay style="width:100%;height:100%;"></video>`;
  document.getElementById('vid-full-overlay').classList.add('open');
}

function closeFullVideo(e) {
  if(e && e.target !== document.getElementById('vid-full-overlay') && !e.target.closest('.vid-full-close')) return;
  document.getElementById('vid-full-overlay').classList.remove('open');
  document.getElementById('vid-full-inner').innerHTML = '';
}

