// ─────────────────────────────────────────────────────────────────────
// saveTimeTrials — guarda los tiempos de contrarreloj del circuito
// seleccionado. Valida el formato con parseQualTime; los vacíos se
// ignoran (no rompen nada — requisito explícito del usuario).
// ─────────────────────────────────────────────────────────────────────
function saveTimeTrials() {
  const sel = document.getElementById('tt-circuit-select');
  if (!sel || !sel.value) { showNotif('⚠ Selecciona un circuito'); return; }
  const round = Number(sel.value);
  if (!S.timeTrials) S.timeTrials = {};

  const times = {};
  const invalid = [];
  document.querySelectorAll('.tt-time-input').forEach(inp => {
    const did = parseInt(inp.dataset.driver, 10);
    const val = (inp.value || '').trim();
    if (!val) return;                       // vacío → se ignora
    if (parseQualTime(val) === null) {      // formato no válido
      invalid.push(val);
      return;
    }
    times[did] = val;
  });
  if (invalid.length) {
    showNotif('⚠ Formato inválido (usa X:XX.XXX): ' + invalid.join(', '));
    return;
  }

  S.timeTrials[round] = { round, times };
  saveState();
  showNotif('✅ Tiempos de contrarreloj guardados');
}

// ─────────────────────────────────────────────────────────────────────
// toggleOddBreakdown — despliega / oculta el panel de desglose de una
// cuota. Sólo actúa con sesión de admin. Construye el panel a partir de
// _lastBetsOdds.breakdown (los mismos números con los que se calculó la
// cuota mostrada). betType: 'victory'|'pole'|...|'safetyCar'.
// key: id de piloto, o 'yes'/'no' para Safety Car.
// ─────────────────────────────────────────────────────────────────────
function toggleOddBreakdown(betType, key, rowEl) {
  if (!document.body.classList.contains('auth-unlocked')) return;  // sólo admin
  if (!rowEl) return;

  // Si ya hay un panel desplegado tras esta fila, lo quita (toggle).
  const next = rowEl.nextElementSibling;
  if (next && next.classList && next.classList.contains('bet-breakdown')) {
    next.remove();
    return;
  }
  // Cierra cualquier otro panel abierto en la página.
  document.querySelectorAll('.bet-breakdown').forEach(el => el.remove());

  if (!_lastBetsOdds || !_lastBetsOdds.breakdown) return;
  const num = (v) => (typeof v === 'number')
    ? (Math.abs(v) >= 100 ? v.toFixed(1) : v.toFixed(3)) : v;

  // Construye una línea del desglose.
  const line = (label, value, note, cls) => `
    <div class="bet-bd-step ${cls || ''}">
      <div class="bet-bd-line">
        <span class="bet-bd-label">${label}</span>
        <span class="bet-bd-value">${value}</span>
      </div>
      ${note ? `<div class="bet-bd-note">${note}</div>` : ''}
    </div>`;

  // Símbolo de la operación de cada paso: × multiplica · + suma ·
  // = subtotal · ^ exponente · λ encogimiento. La base de la apuesta y
  // los pasos informativos no llevan símbolo (no son una operación).
  const _stepSym = { mul: '\u00D7', sum: '+', eq: '=', exp: '^' };
  const bdStep = (st, i) => {
    let label = st.label, op = st.op;
    if (!op) {
      const m = label.match(/^([\u00D7+=]) ?/);
      if (m) { op = { '\u00D7': 'mul', '+': 'sum', '=': 'eq' }[m[1]]; label = label.slice(m[0].length); }
      else op = (i === 0) ? 'base' : 'mul';
    }
    let val = num(st.value);
    if (op === 'shrink') val = '\u03BB = ' + val;
    else if (op !== 'base' && op !== 'info') val = (_stepSym[op] || '') + ' ' + val;
    return line(label, val, st.note);
  };

  let head = '', inner = '';

  if (betType === 'safetyCar') {
    const bd = _lastBetsOdds.breakdown.safetyCar;
    if (!bd) return;
    const side = bd[key];   // 'yes' | 'no'
    head = `Safety Car · ${key === 'yes' ? 'SÍ' : 'NO'}`;
    inner += bd.factorSteps.map((st, i) => bdStep(st, i)).join('');
    inner += `<div class="bet-bd-sep"></div>`;
    inner += line('Probabilidad real', (side.cleanProb * 100).toFixed(1) + '%', 'modelo de Poisson sobre λ', 'bet-bd-prob');
    inner += line('Cuota justa (1/prob)', side.oddFair.toFixed(2), '');
    inner += line('Cuota final (margen 6%)', side.oddFinal.toFixed(2), 'incluye margen de la casa', 'bet-bd-final');
  } else {
    const bdMap = _lastBetsOdds.breakdown[betType];
    if (!bdMap || !bdMap[key]) return;
    const bd = bdMap[key];
    const drvObj = (S.drivers || []).find(d => d.id == key);
    const betNames = { victory:'Ganador', pole:'Pole Position', fastestLap:'Vuelta Rápida',
                       penalty:'Sanción', dnf:'Abandono', overtakeUp:'Gana posiciones',
                       overtakeDown:'Pierde posiciones', absence:'Ausencia' };
    head = `${betNames[betType] || betType} · ${drvObj ? drvObj.name : key}`;
    inner += bd.factorSteps.map((st, i) => bdStep(st, i)).join('');
    inner += `<div class="bet-bd-sep"></div>`;
    if (bd.score != null) {
      inner += line('= Score', num(bd.score), 'producto de los factores anteriores');
    }
    inner += line('Probabilidad real', (bd.cleanProb * 100).toFixed(1) + '%',
                  bd.score != null ? 'score normalizado entre todos los pilotos' : 'probabilidad directa', 'bet-bd-prob');
    inner += line('Cuota justa (1/prob)', bd.oddFair.toFixed(2), 'sin margen ni compresión');
    inner += line('Con margen de la casa', bd.oddMargin.toFixed(2), 'cuota tras aplicar el margen');
    if (bd.compressed) {
      inner += line('Cuota final (comprimida)', bd.oddFinal.toFixed(2),
                    'compresión progresiva, techo 15', 'bet-bd-final');
    } else {
      inner += line('Cuota final', bd.oddFinal.toFixed(2), 'esta apuesta no lleva compresión', 'bet-bd-final');
    }
  }

  const panel = document.createElement('div');
  panel.className = 'bet-breakdown';
  panel.innerHTML = `<div class="bet-bd-head">${head}</div>${inner}`;
  rowEl.parentNode.insertBefore(panel, rowEl.nextSibling);
}



// ─────────────────────────────────────────────────────────────────────
// saveNextGpData — guarda el tipo de qualy y la probabilidad de lluvia
// manual del próximo GP (sección admin de la ficha del circuito).
// Persiste en S.calendario y re-renderiza la ficha.
// ─────────────────────────────────────────────────────────────────────
function saveNextGpData(round) {
  const idx = (S.calendario || []).findIndex(g => Number(g.round) === Number(round));
  if (idx < 0) { showNotif('⚠ GP no encontrado en el calendario'); return; }
  const qtEl = document.getElementById('cd-edit-qualytype');
  const rpEl = document.getElementById('cd-edit-rainpct');
  if (qtEl) {
    S.calendario[idx].qualyType = qtEl.value || null;
  }
  if (rpEl) {
    const v = (rpEl.value || '').trim();
    if (v === '') {
      S.calendario[idx].rainPctManual = null;
    } else {
      let n = parseInt(v, 10);
      if (isNaN(n)) n = 0;
      S.calendario[idx].rainPctManual = Math.max(0, Math.min(100, n));
    }
  }
  saveState();
  delete _renderState['renderBets'];   // las cuotas dependen de estos datos
  openCircuit('next-' + round);         // re-render de la ficha
  showNotif('✅ Datos del próximo GP actualizados');
}









