function editRace(id) {
  const race = S.races.find(r => r.id === id);
  if(!race) return;

  // Force race view with full re-render
  const editIdEl = document.getElementById('edit-race-id');
  if(editIdEl) editIdEl.value = '';
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  const raceView = document.getElementById('view-race');
  if(!raceView) { showNotif('⚠ Error: vista de carrera no encontrada'); return; }
  raceView.classList.add('active');
  renderRaceEntry();
  renderGPHistory();

  // Populate fields
  if(editIdEl) editIdEl.value = race.id;
  const gn = document.getElementById('gp-name-input');     if(gn) gn.value = race.name;
  const gr = document.getElementById('gp-round-input');    if(gr) gr.value = race.round;
  const gf = document.getElementById('gp-flag-input');     if(gf) gf.value = race.countryCode || race.flag || '';
  const gc = document.getElementById('gp-country-input');  if(gc) gc.value = race.country || '';

  S.drivers.forEach(d => {
    const qEl = document.getElementById(`qual-${d.id}`);
    const rEl = document.getElementById(`rpos-${d.id}`);
    const tEl = document.getElementById(`qtime-${d.id}`);
    if(qEl) qEl.value = race.qualResults?.[d.id] || '';
    if(rEl) { const rv = race.results?.[d.id]; rEl.value = rv !== undefined ? rv : ''; }
    if(tEl) {
      const t = race.qualTimes?.[d.id] ?? race.qualTimes?.[String(d.id)];
      tEl.value = t !== undefined ? formatQualTime(t) : '';
    }
  });

  const flSel = document.getElementById('fl-driver-select'); if(flSel) flSel.value = race.fastestLap || '';
  const flT   = document.getElementById('fl-time-input');    if(flT)   flT.value   = race.fastestLapTime || '';
  const poleSel = document.getElementById('pole-driver-select'); if(poleSel) poleSel.value = race.pole || '';

  const sprintCb = document.getElementById('sprint-enabled');
  const sprintSec = document.getElementById('sprint-section');
  if(sprintCb) {
    sprintCb.checked = !!race.sprintResults;
    if(sprintSec) sprintSec.style.display = race.sprintResults ? 'block' : 'none';
    if(race.sprintResults) {
      renderSprintEntry();
      S.drivers.forEach(d => {
        const sEl = document.getElementById(`sprint-${d.id}`);
        if(sEl && race.sprintResults[d.id]) sEl.value = race.sprintResults[d.id];
      });
    }
  }

  const banner = document.getElementById('edit-race-banner');
  const bannerName = document.getElementById('edit-race-banner-name');
  const submitBtn = document.getElementById('submit-race-btn');
  if(banner) banner.style.display = 'block';
  if(bannerName) bannerName.textContent = race.name;
  if(submitBtn) submitBtn.textContent = '💾 Guardar cambios';
  window.scrollTo({ top: 0, behavior: 'smooth' });
  showNotif(`✏️ Editando: ${race.name}`);

  // Sub-paso 2: precargar meteo + SC del race en los inputs nuevos
  if (document.getElementById('race-weather-input')) document.getElementById('race-weather-input').value = race.weather || '';
  if (document.getElementById('race-sc-input'))      document.getElementById('race-sc-input').value      = (race.safetyCarCount != null ? race.safetyCarCount : '');
  // Sub-paso 6: precargar tipo de qualy
  if (document.getElementById('race-qualytype-input')) document.getElementById('race-qualytype-input').value = race.qualyType || '';
}

function submitRace() {
  const name=(document.getElementById('gp-name-input').value||'').trim().toUpperCase();
  const round=parseInt(document.getElementById('gp-round-input').value)||(S.races.length+1);
  const flag=document.getElementById('gp-flag-input').value.trim().toUpperCase().slice(0,2);
  const country=document.getElementById('gp-country-input').value.trim();
  if(!name){showNotif('⚠ Introduce el nombre del GP');return;}
  const results={}, qualResults={};
  let hasRace=false, hasQual=false;
  S.drivers.forEach(d=>{
  const rVal=document.getElementById(`rpos-${d.id}`).value.trim();
  const qVal=document.getElementById(`qual-${d.id}`).value.trim();
  const rp=parseInt(rVal);
  const qp=parseInt(qVal);
  if(rVal!==''&&!isNaN(rp)&&rp>=0){results[d.id]=rp;hasRace=true;}
  if(!isNaN(qp)&&qp>0){qualResults[d.id]=qp;hasQual=true;}
  });
  if(!hasRace){showNotif('⚠ Introduce al menos un resultado de carrera');return;}
  const sprintResults={};
  let hasSprint=false;
  if(document.getElementById('sprint-enabled')?.checked){
  S.drivers.forEach(d=>{
    const sp=parseInt(document.getElementById(`sprint-${d.id}`)?.value);
    if(!isNaN(sp)&&sp>0){sprintResults[d.id]=sp;hasSprint=true;}
  });
  }
  const flVal=parseInt(document.getElementById('fl-driver-select').value)||null;
  const poleVal=parseInt(document.getElementById('pole-driver-select').value)||null;
  const editId=parseInt(document.getElementById('edit-race-id').value);
  // Meteo + SCs (sub-paso 2) + Tipo de Qualy (sub-paso 6): obligatorios.
  const weatherVal = (document.getElementById('race-weather-input')?.value || '').trim();
  const scRaw = (document.getElementById('race-sc-input')?.value || '').trim();
  const qualyTypeVal = (document.getElementById('race-qualytype-input')?.value || '').trim();
  if (!weatherVal) { showNotif('⚠ Selecciona la meteorología de la carrera'); return; }
  if (scRaw === '' || isNaN(parseInt(scRaw,10))) { showNotif('⚠ Introduce el nº de SCs durante la carrera (0 si no hubo)'); return; }
  if (!qualyTypeVal) { showNotif('⚠ Selecciona el tipo de Qualy'); return; }
  const scVal = parseInt(scRaw, 10);
  const raceData={
  name,round,flag,countryCode:flag,country,
  results,qualResults:hasQual?qualResults:{},
  ...(hasSprint?{sprintResults}:{}),
  fastestLap:flVal,pole:poleVal,
  weather: weatherVal,
  safetyCarCount: scVal,
  qualyType: qualyTypeVal,
  ...(((document.getElementById('fl-time-input')?.value||'').trim())?{fastestLapTime:(document.getElementById('fl-time-input')?.value||'').trim()}:{})
  };
  // Save qual times — read all qtime inputs explicitly
  const _qt = {};
  S.drivers.forEach(d => {
    const inputEl = document.getElementById('qtime-' + d.id);
    if (!inputEl) return;
    const raw = (inputEl.value || '').trim();
    if (!raw) return;
    const secs = parseQualTime(raw);
    if (secs !== null) _qt[String(d.id)] = secs;
  });
  if (Object.keys(_qt).length > 0) {
    raceData.qualTimes = _qt;
    showNotif(`⏱ ${Object.keys(_qt).length} tiempos de qualy guardados`);
  } else {
    showNotif('⚠ Sin tiempos de qualy — comprueba formato mm:ss.sss');
  }
  if(editId) {
  const idx=S.races.findIndex(r=>r.id===editId);
  if(idx>-1) S.races[idx]={...S.races[idx],...raceData};
  showNotif(`✅ ${name} actualizado`); updateNavAccent();
  } else {
  archiveOddsSnapshot(raceData);
  S.races.push({id:Date.now(),...raceData});
  S.races.sort((a,b)=>a.round-b.round);
  const newRace=S.races.find(r=>r.name===name&&r.round===round);
  setTimeout(()=>{ if(newRace) checkRecords(newRace); },300);
  showNotif(`✅ ${name} guardado`);
  }
  S.races.sort((a,b)=>a.round-b.round);
  saveState();
  updateLastSaved();
  cancelEditRace();
  renderStandingsIfActive();
  renderGPHistory();
  renderCircuits();
  if(_isViewActive('teams')) renderTeams();
}

function cancelEditRace() {
  document.getElementById('edit-race-id').value='';
  document.getElementById('edit-race-banner').style.display='none';
  document.getElementById('submit-race-btn').textContent='✅ Guardar y actualizar clasificación';
  clearRaceForm();
}

function clearRaceForm() {
  ['gp-name-input','gp-round-input','gp-flag-input','gp-country-input'].forEach(id=>{ const el=document.getElementById(id); if(el)el.value=''; });
  S.drivers.forEach(d=>{
  const r=document.getElementById(`rpos-${d.id}`); if(r)r.value='';
  const q=document.getElementById(`qual-${d.id}`); if(q)q.value='';
  });
  const fl=document.getElementById('fl-driver-select'); if(fl)fl.value='';
  const pole=document.getElementById('pole-driver-select'); if(pole)pole.value='';
  const editId=document.getElementById('edit-race-id'); if(editId)editId.value='';
  const banner=document.getElementById('edit-race-banner'); if(banner)banner.style.display='none';
  const btn=document.getElementById('submit-race-btn'); if(btn)btn.textContent='✅ Guardar y actualizar clasificación';
  const flTimeEl=document.getElementById('fl-time-input'); if(flTimeEl)flTimeEl.value='';
  S.drivers.forEach(d=>{ const el=document.getElementById(`qtime-${d.id}`); if(el)el.value=''; });
  const sprintCb=document.getElementById('sprint-enabled'); if(sprintCb){sprintCb.checked=false; toggleSprintSection();}
  S.drivers.forEach(d=>{ const el=document.getElementById(`sprint-${d.id}`); if(el)el.value=''; });

  // Sub-paso 2
  if (document.getElementById('race-weather-input')) document.getElementById('race-weather-input').value = '';
  if (document.getElementById('race-sc-input'))      document.getElementById('race-sc-input').value      = '';
  // Sub-paso 6
  if (document.getElementById('race-qualytype-input')) document.getElementById('race-qualytype-input').value = '';
}

function deleteRace(id) {
  if(!confirm('¿Mover esta carrera a la papelera?'))return;
  const race=S.races.find(r=>r.id===id);
  if(!race)return;
  if(!S.deletedRaces)S.deletedRaces=[];
  S.deletedRaces.push({...race,deletedAt:Date.now()});
  S.races=S.races.filter(r=>r.id!==id);
  saveState(); renderStandingsIfActive(); renderGPHistory(); renderCircuits();
  if(_isViewActive('teams'))renderTeams();
  showNotif('🗑 Movida a papelera — puedes restaurarla desde Config.');
}

function restoreRace(id) {
  const race=(S.deletedRaces||[]).find(r=>r.id===id);
  if(!race)return;
  const {deletedAt,...raceData}=race;
  S.races.push(raceData);
  S.races.sort((a,b)=>a.round-b.round);
  S.deletedRaces=S.deletedRaces.filter(r=>r.id!==id);
  saveState(); renderStandingsIfActive(); renderGPHistory(); renderTrash();
  showNotif('✅ Carrera restaurada');
}

function permanentDeleteRace(id) {
  if(!confirm('¿Eliminar definitivamente? No se puede deshacer.'))return;
  S.deletedRaces=(S.deletedRaces||[]).filter(r=>r.id!==id);
  saveState(); renderTrash(); showNotif('🗑 Eliminada definitivamente');
}

function saveDriver() {
  const name=document.getElementById('driver-name-input').value.trim().toUpperCase();
  const team=document.getElementById('driver-team-input').value;
  const numRaw=document.getElementById('driver-number-input').value.trim();
  const number=numRaw===''?null:parseInt(numRaw,10);
  const editId=parseInt(document.getElementById('edit-driver-id').value);
  if(!name){showNotif('⚠ Introduce un nombre');return;}
  if(editId){ const d=S.drivers.find(x=>x.id===editId); if(d){d.name=name;d.team=team;d.number=number;} }
  else S.drivers.push({id:Date.now(),name,team,number});
  cancelEditDriver(); saveState(); renderDriversAdmin(); renderStandingsIfActive(); renderRaceEntry();
  showNotif('✅ Piloto guardado');
}

function editDriver(id) {
  const d=S.drivers.find(x=>x.id===id); if(!d)return;
  document.getElementById('driver-name-input').value=d.name;
  document.getElementById('driver-number-input').value=(d.number!=null?d.number:'');
  document.getElementById('driver-team-input').value=d.team;
  document.getElementById('edit-driver-id').value=d.id;
}

function cancelEditDriver() {
  document.getElementById('driver-name-input').value='';
  document.getElementById('driver-number-input').value='';
  document.getElementById('driver-team-input').value='team-mclaren';
  document.getElementById('edit-driver-id').value='';
}

function removeDriver(id) {
  if(!confirm('¿Eliminar este piloto?'))return;
  S.drivers=S.drivers.filter(d=>d.id!==id);
  S.races.forEach(r=>{ delete r.results[id]; delete r.qualResults[id]; if(r.fastestLap===id)r.fastestLap=null; if(r.pole===id)r.pole=null; });
  saveState(); renderDriversAdmin(); renderStandingsIfActive(); renderRaceEntry();
}

function moveDriver(idx,dir) {
  const ni=idx+dir;
  if(ni<0||ni>=S.drivers.length)return;
  [S.drivers[idx],S.drivers[ni]]=[S.drivers[ni],S.drivers[idx]];
  saveState(); renderDriversAdmin();
}

