//  TYPOGRAPHY SYSTEM
const FONT_GROUPS = [
  { id:'portada-title', label:'Portada — Título (FINAL)', var:'--font-portada-title' },
  { id:'nav',           label:'Barra de navegación',      var:'--font-nav' },
  { id:'headings',      label:'Títulos principales (pilotos, escuderías, circuitos)', var:'--font-headings' },
  { id:'tables',        label:'Tablas y clasificaciones', var:'--font-tables' },
  { id:'body',          label:'Textos y notas',           var:'--font-body' },
  { id:'numbers',       label:'Números y puntuaciones',   var:'--font-numbers' },
];

const BUILTIN_FONTS = [
  'Russo One','Barlow Condensed','Orbitron','Exo 2','Rajdhani','Oswald','Bebas Neue'
]

function updateNavAccent() {
  const lastRace = S.races.length ? S.races[S.races.length-1] : null;
  const winnerId = lastRace ? Object.entries(lastRace.results||{}).find(([,p])=>p===1)?.[0] : null;
  const winner = winnerId ? S.drivers.find(d=>d.id===parseInt(winnerId)) : null;
  const accent = winner ? getTeamAccent(winner.team) : 'var(--red)';
  document.documentElement.style.setProperty('--nav-accent', accent);
}

//

function applyFont(fontName) {
  S.selectedFont = fontName;
  saveState();
  _applyFontToDOM(fontName);
  // Update active button
  document.querySelectorAll('.font-choice').forEach(b => {
    b.classList.toggle('active', b.dataset.font === fontName);
  });
  showNotif('✅ Tipografía: ' + fontName);
}

function _applyFontToDOM(fontName) {
  if(!fontName) return;
  // Override --font-display variable
  document.documentElement.style.setProperty('--font-display', `'${fontName}', sans-serif`);
  // Also update Russo One references dynamically
  const styleId = 'leala-font-override';
  let el = document.getElementById(styleId);
  if(!el) { el = document.createElement('style'); el.id = styleId; document.head.appendChild(el); }
  el.textContent = `.profile-hero-name-big, .cd-name, .pts-box, .pstat2-val, .driver-name, .cd-res-pos, .prr-race { font-family: '${fontName}', sans-serif !important; }`;
}

function setFontGroup(groupId, fontName) {
  if(!S.fontGroups) S.fontGroups = {};
  S.fontGroups[groupId] = fontName;
  saveState();
  applyFontGroups();
  renderFontGroupsEditor();
  showNotif(`✅ ${fontName}`);
}

function applyFontGroups() {
  const assigned = S.fontGroups || {};
  const root = document.documentElement;
  FONT_GROUPS.forEach(g => {
    const f = assigned[g.id];
    if(f) root.style.setProperty(g.var, `'${f}', sans-serif`);
  });
}

function uploadCustomFont() {
  const nameEl = document.getElementById('custom-font-name');
  const fileEl = document.getElementById('custom-font-file');
  const file = fileEl?.files[0];
  if(!file) return;
  const name = (nameEl?.value||'').trim() || file.name.replace(/\.[^.]+$/,'');
  if(!name) { showNotif('⚠ Pon un nombre a la fuente'); return; }
  const reader = new FileReader();
  reader.onload = ev => {
    const dataUrl = ev.target.result;
    // Inject @font-face
    injectFontFace(name, dataUrl);
    if(!S.customFonts) S.customFonts = {};
    S.customFonts[name] = dataUrl;
    saveState();
    renderFontGroupsEditor();
    if(nameEl) nameEl.value='';
    showNotif(`✅ Fuente "${name}" cargada`);
  };
  reader.readAsDataURL(file);
}

function injectFontFace(name, dataUrl) {
  const style = document.createElement('style');
  style.textContent = `@font-face { font-family: '${name}'; src: url('${dataUrl}'); }`;
  document.head.appendChild(style);
}

function removeCustomFont(name) {
  if(!confirm(`¿Eliminar la fuente "${name}"?`)) return;
  delete S.customFonts[name];
  // Reset any group using this font
  Object.keys(S.fontGroups||{}).forEach(k => {
    if(S.fontGroups[k]===name) delete S.fontGroups[k];
  });
  saveState();
  applyFontGroups();
  renderFontGroupsEditor();
}

function showView(name, btn) {
  const adminViews = ['race','penalties','drivers-admin','settings'];  // penalties-public is public
  if (adminViews.includes(name) && S.pinEnabled) {
    requirePin(() => _doShowView(name, btn));
    return;
  }
  _doShowView(name, btn);
}

function _doShowView(name, btn) {
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('view-' + name)?.classList.add('active');
  const adminViews2 = ['race','penalties','drivers-admin','settings'];
  if (adminViews2.includes(name)) {
    const tog = document.getElementById('nav-admin-toggle');
    if (tog) tog.classList.add('admin-active');
  } else if (btn) { btn.classList.add('active'); }
  // CAMPEONATO: standings + teams comparten botón nav
  if (name === 'standings' || name === 'teams') {
    const champBtn = document.getElementById('nav-championship-btn');
    if (champBtn) champBtn.classList.add('active');
  }
  // WARCA: noticias + videos + bets comparten botón nav
  if (name === 'noticias' || name === 'videos' || name === 'bets') {
    const warcaBtn = document.getElementById('nav-warca-btn');
    if (warcaBtn) warcaBtn.classList.add('active');
  }
  if (name === 'cover')         { renderPortadaCover(); }
  if (name === 'standings')     renderStandings();
  if (name === 'race') {
    const editActive = document.getElementById('edit-race-id')?.value;
    if (!editActive) { renderRaceEntry(); renderGPHistory(); }
    else { renderQualTimes(); renderGPHistory(); }
  }
  if (name === 'calendario')     { renderCalendario(); }
  if (name === 'noticias')       { renderNoticias(); }
  if (name === 'bets')           { renderBets(); }
  if (name === 'timetrial')      { renderTimeTrial(); }
  if (name === 'circuits')      { renderCircuits(); showCircuitsList(); }
  if (name === 'teams')         { renderTeams(); showTeamsList(); }
  if (name === 'duels')         { populateDuelSelects(); renderDuel(); }
  if (name === 'penalties')     renderPenalties();
  if (name === 'cover')           { renderPortadaCover(); }
  if (name === 'hemeroteca')      renderHemeroteca();
  if (name === 'videos')          renderVideos();
  if (name === 'penalties-public') renderPenaltiesPublic();
  if (name === 'drivers-admin') renderDriversAdmin();
  if (name === 'settings') {
    renderPointsTable();
    renderSprintPointsTable();
    const el = document.getElementById('champ-title-input');
    if (el) el.value = S.championshipTitle;
    renderTrash();
    renderFontGroupsEditor();
    const pinCb = document.getElementById('pin-enabled-toggle');
    // Mark active font
    document.querySelectorAll('.font-choice').forEach(b => {
      b.classList.toggle('active', b.dataset.font === (S.selectedFont||'Russo One'));
    });
    if (pinCb) { pinCb.checked = !!S.pinEnabled; }
    const pinBody = document.getElementById('pin-settings-body');
    if (pinBody) pinBody.style.display = S.pinEnabled ? 'block' : 'none';
    renderTrash();
  }
}

function showNotif(msg) {
  const n=document.getElementById('notif'); if(!n)return; n.textContent=msg; n.classList.add('show');
  setTimeout(()=>n.classList.remove('show'),2800);
}

